control SwitchIngress(
        inout header_t hdr,
        inout metadata_t meta,
        inout standard_metadata_t standard_metadata) {

    action bypass_egress(){

        meta.bypass_egress = 1;

    }
    action dont_bypass_egress(){
        meta.bypass_egress = 0;
    }

    action drop() {
        mark_to_drop(standard_metadata);
        bypass_egress();
    }
    action dont_drop(){

//  Do nothing
    }


    action nop() {
    }
    action route_to(bit<9> port){
        standard_metadata.egress_spec = port;
        hdr.ethernet.src_addr=1; 
        hdr.ethernet.dst_addr=(bit<48>) port; 
    }
    action reflect(){

//send you back to where you're from
        route_to(standard_metadata.ingress_port);
    }

    action do_recirc(){

    }



//siphash init
    action sip_init(bit<32> key_0, bit<32> key_1){
        hdr.sip_meta.setValid();
        hdr.ethernet.ether_type = ETHERTYPE_SIPH_INTM;
        hdr.sip_meta.round = 0;   

        hdr.sip_meta.v_0 = key_0 ^ const_0;
        hdr.sip_meta.v_1 = key_1 ^ const_1;
        hdr.sip_meta.v_2 = key_0 ^ const_2;
        hdr.sip_meta.v_3 = key_1 ^ const_3;

        meta.msg_var = hdr.ipv4.src_addr;
    }

    action sip_init_default_key(){
        bit<32> key_0 = DEFAULT_SIP_KEY_0;
        bit<32> key_1 = DEFAULT_SIP_KEY_1;
        hdr.sip_meta.setValid();
        hdr.ethernet.ether_type=ETHERTYPE_SIPH_INTM;
        hdr.sip_meta.round = 0;   

        hdr.sip_meta.v_0 = key_0 ^ const_0;
        hdr.sip_meta.v_1 = key_1 ^ const_1;
        hdr.sip_meta.v_2 = key_0 ^ const_2;
        hdr.sip_meta.v_3 = key_1 ^ const_3;

        meta.msg_var = hdr.ipv4.src_addr;
    }

    action sip_continue_round4(){
        meta.msg_var = hdr.tcp.src_port ++ hdr.tcp.dst_port;

// will this work? or do I need to use that super complex syntax?
    }
    action sip_continue_round8(){
        meta.msg_var = 0;
    }
    action sip_end_round12_tagack_verify(){

    }

    @pragma stage 0
    table tb_maybe_sip_init {
        key = {
            meta.sip_meta_valid: exact;

            meta.tcp_valid: exact;
            hdr.sip_meta.round: ternary;
        }
        actions = {

            sip_init_default_key;
            sip_continue_round4;
            sip_continue_round8;
            sip_end_round12_tagack_verify;
            nop;
        }
        default_action = nop; 
        size = 16;

    }

    action sip_1_odd(){

        hdr.sip_meta.v_3 = hdr.sip_meta.v_3 ^ meta.msg_var;
    }
    action sip_1_a(){

        meta.a_0 = hdr.sip_meta.v_0 + hdr.sip_meta.v_1;

        meta.a_2 = hdr.sip_meta.v_2 + hdr.sip_meta.v_3;

        meta.a_1 = hdr.sip_meta.v_1[26:0] ++ hdr.sip_meta.v_1[31:27];
    }
    action sip_1_b(){

        meta.a_3 = hdr.sip_meta.v_3[23:0] ++ hdr.sip_meta.v_3[31:24];
    }
    action sip_2_a(){

        hdr.sip_meta.v_1 = meta.a_1 ^ meta.a_0;

        hdr.sip_meta.v_3 = meta.a_3 ^ meta.a_2;

        hdr.sip_meta.v_0 = meta.a_0[15:0] ++ meta.a_0[31:16];

        hdr.sip_meta.v_2 = meta.a_2;
    }
    action sip_3_a(){

        meta.a_2 = hdr.sip_meta.v_2 + hdr.sip_meta.v_1;

        meta.a_0 = hdr.sip_meta.v_0 + hdr.sip_meta.v_3;

        meta.a_1 = hdr.sip_meta.v_1[18:0] ++ hdr.sip_meta.v_1[31:19];
    }
    action sip_3_b(){

        meta.a_3 = hdr.sip_meta.v_3[24:0] ++ hdr.sip_meta.v_3[31:25];
    }

    action sip_4_a(){

        hdr.sip_meta.v_1 = meta.a_1 ^ meta.a_2;

        hdr.sip_meta.v_3 = meta.a_3 ^ meta.a_0;

        hdr.sip_meta.v_2 = meta.a_2[15:0] ++ meta.a_2[31:16];
    }
    action sip_4_b_odd(){

        hdr.sip_meta.v_0 = meta.a_0;
    }
    action sip_4_b_even(){

        hdr.sip_meta.v_0 = meta.a_0 ^ meta.msg_var;
    }


// time-delta


    register< bit<32> >(1) reg_timedelta;




	action timedelta_step0(){
        meta.timestamp_now_copy = TIMESTAMP_NOW_TICK_16;
    }
    action timedelta_step1_write(){
        meta.timestamp_minus_servertime = meta.timestamp_now_copy - hdr.udp_payload.timestamp;
    }
    action timedelta_step2_write(){

        reg_timedelta.write((bit<32>) 0, meta.timestamp_minus_servertime);

    }
    action timedelta_step1_read(){

        reg_timedelta.read(meta.timestamp_minus_servertime, (bit<32>) 0);

    }
    action timedelta_step2_read(){
        hdr.sip_meta.cookie_time = meta.timestamp_now_copy - meta.timestamp_minus_servertime;
	}
	action timedelta_step3_read(){
  		hdr.sip_meta.cookie_time= hdr.sip_meta.cookie_time >> 12;
    }



    register<bit<1>>(32w4096) reg_bloom_1;

    register<bit<1>>(32w4096) reg_bloom_2;







    action set_bloom_1_a(){

        hash(meta.bloom_hash_1, HashAlgorithm.crc16, (bit<32>)0, 
            {hdr.ipv4.src_addr, hdr.ipv4.dst_addr, hdr.tcp.src_port, hdr.tcp.dst_port}, 
            (bit<32>)4095);
        reg_bloom_1.write(meta.bloom_hash_1, (bit<1>) 1);

    }
    action set_bloom_2_a(){

        hash(meta.bloom_hash_2, HashAlgorithm.crc32, (bit<32>)0, 
            {hdr.ipv4.src_addr, hdr.ipv4.dst_addr, hdr.tcp.src_port, hdr.tcp.dst_port}, 
            (bit<32>)4095);
        reg_bloom_2.write(meta.bloom_hash_2, (bit<1>) 1);
    }
    action get_bloom_1_a(){

        hash(meta.bloom_hash_1, HashAlgorithm.crc16, (bit<32>)0, 
            {hdr.ipv4.src_addr, hdr.ipv4.dst_addr, hdr.tcp.src_port, hdr.tcp.dst_port}, 
            (bit<32>)4095);


        reg_bloom_1.read(meta.bloom_read_1, meta.bloom_hash_1);
    }
    action get_bloom_2_a(){

        hash(meta.bloom_hash_2, HashAlgorithm.crc32, (bit<32>)0, 
            {hdr.ipv4.src_addr, hdr.ipv4.dst_addr, hdr.tcp.src_port, hdr.tcp.dst_port}, 
            (bit<32>)4095);
        reg_bloom_2.read(meta.bloom_read_2, meta.bloom_hash_2);
    }


// packet in-out related

    action naive_routing(){
        standard_metadata.egress_spec = (bit<9>) hdr.ipv4.dst_addr[31:24];
        hdr.ethernet.src_addr=1;
        hdr.ethernet.dst_addr[47:8] = 0; 
        hdr.ethernet.dst_addr[7:0] = hdr.ipv4.dst_addr[31:24];
    }

    action craft_onward_ack(){
        hdr.tcp.seq_no = hdr.tcp.seq_no - 1;
        hdr.tcp.data_offset = 5;

//add setup tag
        hdr.tcp.flag_ece = 1;
    }


    action client_to_server_nonsyn_ongoing(){
        route_to(SERVER_PORT);
        bypass_egress();

        hdr.sip_meta.setInvalid();
        hdr.ethernet.ether_type=ETHERTYPE_IPV4; 
    }
    action server_to_client_normal_traffic(){
        hdr.sip_meta.setInvalid();
        hdr.ethernet.ether_type=ETHERTYPE_IPV4;
        naive_routing();
        bypass_egress();

    }
    action non_tcp_traffic(){
        naive_routing();
        bypass_egress();

    }

// hash calc
    action start_sipcalc_synack(){
        hdr.sip_meta.callback_type=CALLBACK_TYPE_SYNACK;
        hdr.sip_meta.egr_port=standard_metadata.ingress_port;


        hdr.sip_meta.round=2;

        dont_bypass_egress(); 

    }
    action start_sipcalc_tagack(){
        hdr.sip_meta.callback_type=CALLBACK_TYPE_TAGACK;
        hdr.sip_meta.egr_port=SERVER_PORT; 

        hdr.sip_meta.round=2;

        dont_bypass_egress();

    }
    action continue_sipcalc_round4to6(){
        hdr.sip_meta.round=6;

        dont_bypass_egress();

    }
    action pre_finalize_synack(){
        hdr.sip_meta.round=10;
        route_to(hdr.sip_meta.egr_port);
        dont_bypass_egress();

    }
    action pre_finalize_tagack(){
        hdr.sip_meta.round=10;

        dont_bypass_egress();

    }

    action finalize_tagack(){
        route_to(hdr.sip_meta.egr_port);

//don't bypass egress, perform checksum update in egress deparser
        dont_bypass_egress();
        hdr.sip_meta.round=99;


        if (meta.ack_verify_timediff_exceeded_limit == 1) {
        mark_to_drop(standard_metadata);
        }

        craft_onward_ack();

    }

    @pragma stage 11
    table tb_triage_pkt_types_nextstep {
        key = {
            hdr.sip_meta.round: exact;
            meta.tcp_valid: exact;
            meta.udp_payload_valid: exact;

            meta.ingress_is_server_port: ternary;

            meta.flag_syn: ternary;
            meta.flag_ack: ternary;
            meta.flag_ece: ternary; 

            hdr.sip_meta.callback_type: ternary;

            meta.bloom_read_passed: ternary;
        }
        actions = {
            drop;
            start_sipcalc_synack;
            start_sipcalc_tagack;
            client_to_server_nonsyn_ongoing;
            server_to_client_normal_traffic;
            non_tcp_traffic;

            continue_sipcalc_round4to6;
            pre_finalize_synack;
            pre_finalize_tagack;
            finalize_tagack;
        }
        default_action = drop();







        size = 32;
    }


    apply {    

//stage 0
        tb_maybe_sip_init.apply();


//calculate all other cases in parallel
        timedelta_step0();
        if(meta.udp_payload_valid == 1 && standard_metadata.ingress_port==SERVER_PORT){
            timedelta_step1_write();
            timedelta_step2_write();

        }else{
            timedelta_step1_read();
            timedelta_step2_read();
            timedelta_step3_read();
        }

        if(meta.tcp_valid == 1 && standard_metadata.ingress_port == SERVER_PORT && hdr.tcp.flag_ece==1){
            set_bloom_1_a();
            set_bloom_2_a();
            meta.bloom_read_passed=0;

        }else{
            get_bloom_1_a();
            get_bloom_2_a();
            if(meta.bloom_read_1==1 && meta.bloom_read_2==1){
                meta.bloom_read_passed=1;
            }else{
                meta.bloom_read_passed=0;
            }
        }


//pre-calculate conditions and save in metadata. used in final stage triage.
        if(standard_metadata.ingress_port==SERVER_PORT){
            meta.ingress_is_server_port = 1;
        }else{
            meta.ingress_is_server_port = 0;
        }

        if(hdr.sip_meta.ack_verify_timediff==0 || hdr.sip_meta.ack_verify_timediff==1 || hdr.sip_meta.ack_verify_timediff==2){
            meta.ack_verify_timediff_exceeded_limit=0;
        }else{
            meta.ack_verify_timediff_exceeded_limit=1;
        }



//calculate siphash 2 round
        sip_1_odd();

        sip_1_a();
        sip_1_b();
        sip_2_a();
        sip_3_a();
        sip_3_b();
        sip_4_a();
        sip_4_b_odd();

//second SipRound
        sip_1_a();
        sip_1_b();
        sip_2_a();
        sip_3_a();
        sip_3_b();
        sip_4_a(); 
        sip_4_b_even();




        if(meta.tcp_valid == 1){
            meta.flag_syn=hdr.tcp.flag_syn;
            meta.flag_ack=hdr.tcp.flag_ack;
            meta.flag_ece=hdr.tcp.flag_ece;
        }
        else{
            meta.flag_syn=0;
            meta.flag_ack=0;
            meta.flag_ece=0;
        }



// // Generate a pseudo-random bit
        bit<1> rnd;
        hash(rnd, HashAlgorithm.crc16, (bit<32>)0, {hdr.ipv4.src_addr, hdr.ipv4.dst_addr, hdr.tcp.src_port, hdr.tcp.dst_port}, (bit<32>)1);
        if (rnd == 1) {
            route_to(68);
        } else {
            route_to(68+128);
        }

        tb_triage_pkt_types_nextstep.apply();
    }
}


control SwitchEgress(
        inout header_t hdr,
        inout metadata_t meta,
        inout standard_metadata_t standard_metadata) {


    action sip_1_odd(){

        hdr.sip_meta.v_3 = hdr.sip_meta.v_3 ^ meta.msg_var;
    }
    action sip_1_a(){

        meta.a_0 = hdr.sip_meta.v_0 + hdr.sip_meta.v_1;

        meta.a_2 = hdr.sip_meta.v_2 + hdr.sip_meta.v_3;

        meta.a_1 = (hdr.sip_meta.v_1 << 5) | (hdr.sip_meta.v_1 >> (32 - 5));

    }
    action sip_1_b(){

        meta.a_3 = (hdr.sip_meta.v_3 << 8) | (hdr.sip_meta.v_3 >> 24);
    }
    action sip_2_a(){

        hdr.sip_meta.v_1 = meta.a_1 ^ meta.a_0;

        hdr.sip_meta.v_3 = meta.a_3 ^ meta.a_2;

        hdr.sip_meta.v_0 = (meta.a_0 << 16) | (meta.a_0 >> (32 - 16));

        hdr.sip_meta.v_2 = meta.a_2;
    }
    action sip_3_a(){

        meta.a_2 = hdr.sip_meta.v_2 + hdr.sip_meta.v_1;

        meta.a_0 = hdr.sip_meta.v_0 + hdr.sip_meta.v_3;

        meta.a_1 = (hdr.sip_meta.v_1 << 13) | (hdr.sip_meta.v_1 >> (32 - 13));

    }
    action sip_3_b(){

        meta.a_3 = (hdr.sip_meta.v_3 << 7) | (hdr.sip_meta.v_3 >> (32 - 7));

// Left rotate by 7
    }

    action sip_4_a(){

        hdr.sip_meta.v_1 = meta.a_1 ^ meta.a_2;

        hdr.sip_meta.v_3 = meta.a_3 ^ meta.a_0;

        hdr.sip_meta.v_2 = (meta.a_2 << 16) | (meta.a_2 >> (32 - 16));

// Left rotate by 16
    }
    action sip_4_b_odd(){

        hdr.sip_meta.v_0 = meta.a_0;
    }
    action sip_4_b_even(){

        hdr.sip_meta.v_0 = meta.a_0 ^ meta.msg_var;
    }



    action clean_up(){

        meta.sip_meta_valid = 0;
        hdr.ethernet.ether_type=ETHERTYPE_IPV4; 
    }


    action sip_final_xor_with_time(){
        hdr.tcp.seq_no = hdr.sip_meta.cookie_time ^ hdr.sip_meta.v_0 ^ hdr.sip_meta.v_1 ^ hdr.sip_meta.v_2 ^ hdr.sip_meta.v_3;
        clean_up();
    }

    action sip_final_xor_with_ackm1(){
        meta.cookie_val = meta.incoming_ack_minus_1 ^ hdr.sip_meta.v_0 ^ hdr.sip_meta.v_1 ^ hdr.sip_meta.v_2 ^ hdr.sip_meta.v_3;
    }

	action verify_timediff(){
	    hdr.sip_meta.ack_verify_timediff = hdr.sip_meta.cookie_time - meta.cookie_val;

// should be 0 or 1
	}

    action craft_synack_reply(){
        hdr.tcp.ack_no=meta.incoming_seq_plus_1;



//swap IP
        bit<32> tmp_ip = hdr.ipv4.src_addr;
        hdr.ipv4.src_addr = hdr.ipv4.dst_addr;
        hdr.ipv4.dst_addr = tmp_ip;


//swap port
    	bit<16> tmp_port = hdr.tcp.src_port;  
        hdr.tcp.src_port=hdr.tcp.dst_port;
        hdr.tcp.dst_port=tmp_port;


//packet crafting
        hdr.tcp.data_offset=5;

        hdr.tcp.flag_ack=1;
        hdr.tcp.flag_syn=1;

        hdr.ipv4.ihl=5;
        hdr.ipv4.total_len=40; 


//necessary for checksum update
        meta.redo_checksum=1;
        meta.tcp_total_len=20; 


//routing done in ingress
    }

    action drop(){
        mark_to_drop(standard_metadata);
    }
    action dont_drop(){

// packet is automatically forwarded
    }

    action nop() {
    }

    table tb_decide_output_type_1 {
        key = {
            meta.sip_meta_valid: exact;
            meta.tcp_valid: exact;
            hdr.sip_meta.round: exact;
            hdr.sip_meta.callback_type: ternary;

        }
        actions = {
            craft_synack_reply; 
            sip_final_xor_with_ackm1;
            clean_up;
            nop;
        }
        default_action = nop;
        size = 16;

    }

    table tb_decide_output_type_2 {
        key = {
            meta.sip_meta_valid: exact;
            meta.tcp_valid: exact;
            hdr.sip_meta.round: exact;
            hdr.sip_meta.callback_type: ternary;
        }
        actions = {
            sip_final_xor_with_time;
            verify_timediff;
            nop;
        }
        default_action = nop;
        size = 16;

    }

    apply {
        if(meta.bypass_egress == 0){

//stage 0
            if(hdr.sip_meta.round==2){
                meta.msg_var = hdr.ipv4.dst_addr;
            }else
            if(hdr.sip_meta.round==6 && hdr.sip_meta.callback_type==CALLBACK_TYPE_SYNACK){
                meta.msg_var = hdr.tcp.seq_no;
            }else 
            if(hdr.sip_meta.round==6 && hdr.sip_meta.callback_type==CALLBACK_TYPE_TAGACK){
                meta.msg_var = hdr.tcp.seq_no - 1;
            }else 
            if(hdr.sip_meta.round==10){ 
                meta.msg_var = 0;

// final compression rounds is 8,9,10,11
            }

            if(hdr.sip_meta.round != 99){

                sip_1_odd();

//first SipRound
                sip_1_a();
                sip_1_b();
                sip_2_a();
                sip_3_a();
                sip_3_b();
                sip_4_a();
                sip_4_b_odd();

//second SipRound
                sip_1_a();
                sip_1_b();
                sip_2_a();
                sip_3_a();
                sip_3_b();
                sip_4_a();

                sip_4_b_even();
                hdr.sip_meta.round=hdr.sip_meta.round+2;

                meta.incoming_ack_minus_1=hdr.tcp.ack_no - 1;
                meta.incoming_seq_plus_1=hdr.tcp.seq_no + 1;
                meta.tcp_total_len=20;

                meta.redo_checksum=0;

                tb_decide_output_type_1.apply(); 	 
                tb_decide_output_type_2.apply(); 
            }

            else{



//necessary for checksum update
                hdr.ipv4.ihl=5;
                hdr.ipv4.total_len=40; 

                meta.redo_checksum=1;
                meta.tcp_total_len=20; 

                meta.sip_meta_valid = 0;
                hdr.ethernet.ether_type=ETHERTYPE_IPV4;
            }
        }
    }

// apply
}



control MyVerifyChecksum(inout header_t hdr, inout metadata_t meta) {
    apply {
     verify_checksum(
	    hdr.ipv4.isValid(),
            { hdr.ipv4.version,
	      hdr.ipv4.ihl,
              hdr.ipv4.diffserv,
              hdr.ipv4.total_len,
              hdr.ipv4.identification,
              hdr.ipv4.flags,
              hdr.ipv4.frag_offset,
              hdr.ipv4.ttl,
              hdr.ipv4.protocol,
              hdr.ipv4.src_addr,
              hdr.ipv4.dst_addr},
            hdr.ipv4.hdr_checksum,
            HashAlgorithm.csum16);
     }
}



control MyComputeChecksum(inout header_t hdr, inout metadata_t meta) {
     apply {
	update_checksum(
	    hdr.ipv4.isValid(),
            { hdr.ipv4.version,
	      hdr.ipv4.ihl,
              hdr.ipv4.diffserv,
              hdr.ipv4.total_len,
              hdr.ipv4.identification,
              hdr.ipv4.flags,
              hdr.ipv4.frag_offset,
              hdr.ipv4.ttl,
              hdr.ipv4.protocol,
              hdr.ipv4.src_addr,
              hdr.ipv4.dst_addr },
            hdr.ipv4.hdr_checksum,
            HashAlgorithm.csum16);

        update_checksum_with_payload(
	    hdr.tcp.isValid() && hdr.ipv4.isValid(),
            { hdr.ipv4.src_addr,
	      hdr.ipv4.dst_addr,
              8w0,
              hdr.ipv4.protocol,
              meta.tcp_total_len,
              hdr.tcp.src_port,
              hdr.tcp.dst_port,
              hdr.tcp.seq_no,
              hdr.tcp.ack_no,
              hdr.tcp.data_offset,
              hdr.tcp.res,
              hdr.tcp.flag_cwr,
              hdr.tcp.flag_ece,
              hdr.tcp.flag_urg,
              hdr.tcp.flag_ack,
              hdr.tcp.flag_psh,
              hdr.tcp.flag_rst,
              hdr.tcp.flag_syn,
              hdr.tcp.flag_fin,
              hdr.tcp.window,
              hdr.tcp.urgent_ptr
              },
            hdr.tcp.checksum,
            HashAlgorithm.csum16);

    }
}


V1Switch(
    SwitchIngressParser(),
    MyVerifyChecksum(),
    SwitchIngress(),

    SwitchEgress(),
    MyComputeChecksum(),
    SwitchEgressDeparser()
) main;


// Switch(pipe) main;

#include <core.p4>
#include <v1model.p4>

#ifndef FILTER_SIZE
#define FILTER_SIZE 32w4096
#endif

#ifndef FILTER_SIZE_MINUS_ONE
#define FILTER_SIZE_MINUS_ONE 4095
#endif

#define STAGE_SIZE_MINUS_ONE FILTER_SIZE_MINUS_ONE
#define BLOOM_STAGE_SIZE FILTER_SIZE

typedef bit<48> mac_addr_t;
typedef bit<32> ipv4_addr_t;
typedef bit<16> ether_type_t;
const ether_type_t ETHERTYPE_IPV4 = 16w0x0800;
const ether_type_t ETHERTYPE_SIPH_INTM = 16w0xff00;


// Testbed parameters
const bit<9> SERVER_PORT=3; 

typedef bit<8> ip_protocol_t;
typedef bit<9> egress_spec_t;
const ip_protocol_t IP_PROTOCOLS_ICMP = 1;
const ip_protocol_t IP_PROTOCOLS_TCP = 6;
const ip_protocol_t IP_PROTOCOLS_UDP = 17;

const bit<16> PORT_TIMEDELTA_UPDATE = 5555;

// for time delta

const bit<4> CALLBACK_TYPE_SYNACK=1;
const bit<4> CALLBACK_TYPE_TAGACK=2; 

struct paired_32bit {
    bit<32> lo;
    bit<32> hi;
}

header ethernet_h {
    mac_addr_t dst_addr;
    mac_addr_t src_addr;
    bit<16> ether_type;
}

header ipv4_h {
    bit<4> version;
    bit<4> ihl;
    bit<8> diffserv;
    bit<16> total_len;
    bit<16> identification;
    bit<3> flags;
    bit<13> frag_offset;
    bit<8> ttl;
    bit<8> protocol;
    bit<16> hdr_checksum;
    ipv4_addr_t src_addr;
    ipv4_addr_t dst_addr;
}

header tcp_h {
    bit<16> src_port;
    bit<16> dst_port;

    bit<32> seq_no;
    bit<32> ack_no;
    bit<4> data_offset;
    bit<4> res;

//
    bit<1> flag_cwr;
    bit<1> flag_ece; 

//
    bit<1> flag_urg;
    bit<1> flag_ack;
    bit<1> flag_psh;
    bit<1> flag_rst;
    bit<1> flag_syn;
    bit<1> flag_fin;

//
    bit<16> window;
    bit<16> checksum;
    bit<16> urgent_ptr;
}

header udp_h {
    bit<16> src_port;
    bit<16> dst_port;
    bit<16> udp_total_len;
    bit<16> checksum;
}

header udp_payload_h {
    bit<32> timestamp;
}

struct header_t {
    ethernet_h ethernet;
    ipv4_h ipv4;
    tcp_h tcp;
    udp_h udp;
    udp_payload_h udp_payload;
}

struct metadata_t {

// Header validity bits for use in tables
    bit<1> tcp_valid;
    bit<1> udp_payload_valid;


// Timestamping
    bit<32> timestamp_now_copy;
    bit<32> timestamp_minus_servertime;


// Bloom Filter
    bit<1> bloom_read_1;

    bit<32> bloom_hash_1;

    bit<1> bloom_read_passed;



// Packet metadata
    bit<1> ingress_is_server_port;

    bit<32> incoming_ack_minus_1;
    bit<32> incoming_seq_plus_1;

    bit<16> tcp_len;


// Cookie-related
    bit<32> cookie_hash;
    bit<32> cookie_val;
    bit<32> cookie_time;
    bit<32> ack_verify_timediff;
    bit<1> ack_verify_timediff_exceeded_limit;


// Cookie control flow
    bit<4> callback_type;
    bit<1> bypass_egress;
    bit<1> skip_routing;
    bit<9> egr_port;

    standard_metadata_t standard_metadata;
}

parser SwitchIngressParser(
        packet_in pkt,
        out header_t hdr,
        inout metadata_t meta,
        inout standard_metadata_t standard_metadata) {


    state start {
        transition parse_ethernet;
    }

    state parse_ethernet {
        pkt.extract(hdr.ethernet);
        transition select (hdr.ethernet.ether_type) {
            ETHERTYPE_IPV4 : parse_ipv4;
            default : accept;
        }
    }

    state parse_ipv4 {
        pkt.extract(hdr.ipv4);
        transition select(hdr.ipv4.protocol) {
            IP_PROTOCOLS_TCP : parse_tcp;
            IP_PROTOCOLS_UDP : parse_udp;
            default : accept;
        }
    }

    state parse_tcp {
        pkt.extract(hdr.tcp);
        meta.tcp_valid = 1;
        transition select(hdr.ipv4.total_len) {
            default : accept;
        }
    }

    state parse_udp {
        pkt.extract(hdr.udp);
        transition select(hdr.udp.dst_port) {
            PORT_TIMEDELTA_UPDATE: parse_udp_payload;
            default: accept;
        }
    }

    state parse_udp_payload {
        pkt.extract(hdr.udp_payload);
        meta.udp_payload_valid = 1;
        transition accept;
    }
}



control MyVerifyChecksum(inout header_t hdr, inout metadata_t meta) {
    apply {
     verify_checksum(
	    hdr.ipv4.isValid(),
            { hdr.ipv4.version,
	      hdr.ipv4.ihl,
              hdr.ipv4.diffserv,
              hdr.ipv4.total_len,
              hdr.ipv4.identification,
              hdr.ipv4.flags,
              hdr.ipv4.frag_offset,
              hdr.ipv4.ttl,
              hdr.ipv4.protocol,
              hdr.ipv4.src_addr,
              hdr.ipv4.dst_addr},
            hdr.ipv4.hdr_checksum,
            HashAlgorithm.csum16);
     }
}



control SwitchIngress(
        inout header_t hdr,
        inout metadata_t meta,
        inout standard_metadata_t standard_metadata) {

    action bypass_egress(){

// bypass final step "egress"
        meta.bypass_egress = 1;
    }
    action dont_bypass_egress(){

// don't bypass final step "egress"
        meta.bypass_egress = 0;
    }

    action skip_routing(){

// skip table based IPv4 forwarding
        meta.skip_routing = 1;
    }

    action drop() {

// drops the packet as quick as possible
        mark_to_drop(standard_metadata);
        bypass_egress();
        skip_routing();
    }



// time-delta

    register< bit<32> >(1) reg_timedelta;

	action timedelta_step0(){
        meta.timestamp_now_copy = (bit<32>) standard_metadata.ingress_global_timestamp[47:16];
    }


// to specify the time delta between server and proxy application
    action timedelta_step1_write(){
        meta.timestamp_minus_servertime = meta.timestamp_now_copy - hdr.udp_payload.timestamp;
    }

    action timedelta_step2_write(){
        reg_timedelta.write((bit<32>) 0, meta.timestamp_minus_servertime);

    }


// calculate the actual cookie time as it would be at the server itself
    action timedelta_step1_read(){
        reg_timedelta.read(meta.timestamp_minus_servertime, (bit<32>) 0);
    }

    action timedelta_step2_read(){
       meta.cookie_time = meta.timestamp_now_copy - meta.timestamp_minus_servertime;
       if (meta.cookie_time == 0) {

        meta.cookie_time = 0;
       }
	}

	action timedelta_step3_read(){
  		meta.cookie_time = meta.cookie_time >> 7;

        reg_timedelta.write((bit<32>) 0, meta.cookie_time);
    }


    register<bit<1>>(BLOOM_STAGE_SIZE) reg_bloom_0_1;



// Bloom Filter #1
    register<bit<1>>(BLOOM_STAGE_SIZE) reg_bloom_1_1;



    action set_bloom_1_a(){
        hash(meta.bloom_hash_1, HashAlgorithm.crc16, (bit<32>)0, 
            {hdr.ipv4.src_addr, hdr.ipv4.dst_addr, hdr.tcp.src_port, hdr.tcp.dst_port}, 
            (bit<32>)STAGE_SIZE_MINUS_ONE);

        reg_bloom_0_1.write(meta.bloom_hash_1, (bit<1>) 1);
        reg_bloom_1_1.write(meta.bloom_hash_1, (bit<1>) 1);
    }


    action read_sync_bloom_1(){
        reg_bloom_0_1.read(meta.bloom_read_1, meta.bloom_hash_1);
        if (meta.bloom_read_1 == 0) {
            reg_bloom_1_1.read(meta.bloom_read_1, meta.bloom_hash_1);

// either write 0 in it again or write 1
            reg_bloom_0_1.write(meta.bloom_hash_1, (bit<1>) meta.bloom_read_1);
        } else {
            reg_bloom_1_1.write(meta.bloom_hash_1, (bit<1>) meta.bloom_read_1);
        }
    }

    action get_bloom_1_a(){
        hash(meta.bloom_hash_1, HashAlgorithm.crc16, (bit<32>)0, 
            {hdr.ipv4.src_addr, hdr.ipv4.dst_addr, hdr.tcp.src_port, hdr.tcp.dst_port}, 
            (bit<32>)STAGE_SIZE_MINUS_ONE);

        read_sync_bloom_1();
    }




    action client_to_server_nonsyn_ongoing(){
        bypass_egress();
    }

    action server_to_client_normal_traffic(){
        bypass_egress();
    }

    action non_tcp_traffic(){
        bypass_egress();
    }


// Hash Calculation


// create cookie hash
    action start_crc_calc_synack() {
        meta.callback_type = CALLBACK_TYPE_SYNACK;

// reroute to ingress port
        meta.egr_port = standard_metadata.ingress_port; 


// Compute CRC32 hash and store in metadata
        hash(meta.cookie_hash, HashAlgorithm.crc32, (bit<32>) 0, 
            { hdr.ipv4.src_addr, hdr.ipv4.dst_addr, hdr.tcp.src_port, hdr.tcp.dst_port, hdr.tcp.seq_no }, 
            (bit<32>) 65535);

    }


// create cookie hash for later verification
    action start_crc_calc_tagack() {
        meta.callback_type = CALLBACK_TYPE_TAGACK;

// reroute to server port
        meta.egr_port = SERVER_PORT;
        bit<32> seq_no_minusone = hdr.tcp.seq_no - 1;


// Compute CRC32 hash and store in metadata
        hash(meta.cookie_hash, HashAlgorithm.crc32, (bit<32>) 0, 
            { hdr.ipv4.src_addr, hdr.ipv4.dst_addr, hdr.tcp.src_port, hdr.tcp.dst_port, seq_no_minusone }, 
            (bit<32>) 65535);
    }



    table tb_triage_pkt_types_nextstep {
        key = {
            meta.tcp_valid: exact;
            meta.udp_payload_valid: exact;

            meta.ingress_is_server_port: ternary;

            hdr.tcp.flag_syn: ternary;
            hdr.tcp.flag_ack: ternary;
            hdr.tcp.flag_ece: ternary; 

            meta.callback_type: ternary;

            meta.bloom_read_passed: ternary;
        }
        actions = {
            drop;

            start_crc_calc_synack;
            start_crc_calc_tagack;

            client_to_server_nonsyn_ongoing;
            server_to_client_normal_traffic;

            non_tcp_traffic;

        }
        default_action = drop();





        size = 32;
    }


// forward packet to the appropriate port
    action ipv4_forward(mac_addr_t dst_addr, egress_spec_t port) {
        standard_metadata.egress_spec = port;
        hdr.ethernet.src_addr = hdr.ethernet.dst_addr;
        hdr.ethernet.dst_addr = dst_addr;
        hdr.ipv4.ttl = hdr.ipv4.ttl - 1;
    }


// we have one table responsible for forwarding packets
    table tb_ipv4_lpm {
        key = {
            hdr.ipv4.dst_addr: lpm;
        }
        actions = {
            ipv4_forward;
            drop;
            NoAction;
        }
        size = 1024;

// maximum number of entries in the table
        default_action = drop();
    }

    action final_xor_with_time(){
        hdr.tcp.seq_no = meta.cookie_hash ^ meta.cookie_time;
    }

	action verify_timediff(){
	    meta.ack_verify_timediff = meta.cookie_time - meta.cookie_val;

// should be 0 or 1
	}

    action final_xor_with_ackm1(){
        meta.cookie_val = meta.incoming_ack_minus_1 ^ meta.cookie_hash;
    }

    action verify_ack(){
        final_xor_with_ackm1();
        verify_timediff();
    }

    action craft_synack_reply(){
        hdr.tcp.ack_no = meta.incoming_seq_plus_1;

	   final_xor_with_time();



//swap IP
        bit<32> tmp_ip = hdr.ipv4.src_addr;
        hdr.ipv4.src_addr = hdr.ipv4.dst_addr;
        hdr.ipv4.dst_addr = tmp_ip;


//swap port
    	bit<16> tmp_port = hdr.tcp.src_port;  
        hdr.tcp.src_port=hdr.tcp.dst_port;
        hdr.tcp.dst_port=tmp_port;


//packet crafting
        hdr.tcp.data_offset=5;


        hdr.tcp.flag_ack=1;
        hdr.tcp.flag_syn=1;

        hdr.ipv4.ihl=5;
    }

    table tb_decide_output_type {
        key = {

            meta.tcp_valid: exact;

            meta.callback_type: ternary;
        }
        actions = {
            craft_synack_reply; 
            verify_ack;

            NoAction;
        }
        default_action = NoAction;
        size = 16;

    }

    action craft_onward_ack(){
        hdr.tcp.seq_no = hdr.tcp.seq_no - 1;
        hdr.tcp.data_offset = 5;

//add setup tag
        hdr.tcp.flag_ece = 1;
    }

    action finalize_tagack(){
        if (meta.ack_verify_timediff_exceeded_limit == 1) {
            mark_to_drop(standard_metadata);
        }
        craft_onward_ack();
    }

    action compute_tcp_length(){
        bit<16> tcpLength;
        bit<16> ipv4HeaderLength = ((bit<16>) hdr.ipv4.ihl) * 4;

        tcpLength = hdr.ipv4.total_len - ipv4HeaderLength;

// save this value to metadata to be used later in checksum computation
        meta.tcp_len = tcpLength;
    }









    apply {


// Timedelta verification and setup
        timedelta_step0();
        if(hdr.udp.isValid() && standard_metadata.ingress_port == SERVER_PORT){
            timedelta_step1_write();
            timedelta_step2_write();
        }else{
            timedelta_step1_read();
            timedelta_step2_read();
            timedelta_step3_read();
        }


// Check if Bloom Filter time-decaying mechanism has to run


// Bloom Filter set and get

        if(hdr.tcp.isValid() && standard_metadata.ingress_port == SERVER_PORT && hdr.tcp.flag_ece==1){
            set_bloom_1_a();

            meta.bloom_read_passed=0;
        }else{
            get_bloom_1_a();

            if(meta.bloom_read_1==1){

                meta.bloom_read_passed=1;
            }else{
                meta.bloom_read_passed=0;
            }
        }


// pre-calculate conditions and save in metadata. used in final stage triage.
        if(standard_metadata.ingress_port==SERVER_PORT){
            meta.ingress_is_server_port = 1;
        }else{
            meta.ingress_is_server_port = 0;
        }

        tb_triage_pkt_types_nextstep.apply();



// final packet processing stage: "egress"

        if(meta.bypass_egress == 0){
            meta.incoming_ack_minus_1 = hdr.tcp.ack_no - 1;
            meta.incoming_seq_plus_1 = hdr.tcp.seq_no + 1;

            tb_decide_output_type.apply(); 

            if(meta.callback_type == CALLBACK_TYPE_TAGACK){

                if(meta.ack_verify_timediff==0){

                    meta.ack_verify_timediff_exceeded_limit=0;
                }else{
                    meta.ack_verify_timediff_exceeded_limit=1;
                    mark_to_drop(standard_metadata);
                    skip_routing();
                }

                if(hdr.tcp.isValid() && !hdr.udp.isValid() && meta.callback_type == CALLBACK_TYPE_TAGACK){
                    finalize_tagack();
                }

// necessary for checksum update
                hdr.ipv4.ihl=5;
                hdr.ipv4.total_len=40;
            }

        }

        compute_tcp_length();


// Normal forwarding scenario after processing based on the scenario
        if (meta.skip_routing == 0 && hdr.ipv4.isValid()) {
            tb_ipv4_lpm.apply();
        }
    }
}


control SwitchEgress(
        inout header_t hdr,
        inout metadata_t meta,
