#include <core.p4>
#include <v1model.p4>

const bit<16> TYPE_IPV4 = 0x800;
const bit<16> TYPE_HULA = 0x2345;

#define MAX_HOPS  9
#define TOR_NUM   32
#define TOR_NUM_1 33



typedef bit<9>  egressSpec_t;
typedef bit<48> macAddr_t;
typedef bit<32> ip4Addr_t;
typedef bit<15> qdepth_t;
typedef bit<32> digest_t;

header ethernet_t {
    macAddr_t dstAddr;
    macAddr_t srcAddr;
    bit<16>   etherType;
}

header srcRoute_t {
    bit<1>    bos;
    bit<15>   port;
}

header hula_t {

/* 0 is forward path, 1 is the backward path */
    bit<1>   dir;

/* max qdepth seen so far in the forward path */
    qdepth_t qdepth;

/* digest of the source routing list to uniquely identify each path */
    digest_t digest;
}

header ipv4_t {
    bit<4>    version;
    bit<4>    ihl;
    bit<8>    diffserv;
    bit<16>   totalLen;
    bit<16>   identification;
    bit<3>    flags;
    bit<13>   fragOffset;
    bit<8>    ttl;
    bit<8>    protocol;
    bit<16>   hdrChecksum;
    ip4Addr_t srcAddr;
    ip4Addr_t dstAddr;
}

header udp_t {
    bit<16> srcPort;
    bit<16> dstPort;
    bit<16> length_;
    bit<16> checksum;
}

struct metadata {

    bit<32> index;
}

struct headers {
    ethernet_t              ethernet;
    srcRoute_t[MAX_HOPS]    srcRoutes;
    ipv4_t                  ipv4;
    udp_t                   udp;
    hula_t                  hula;
}



parser MyParser(packet_in packet,
                out headers hdr,
                inout metadata meta,
                inout standard_metadata_t standard_metadata) {

    state start {
        transition parse_ethernet;
    }

    state parse_ethernet {
        packet.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType) {
            TYPE_HULA : parse_hula;
            TYPE_IPV4 : parse_ipv4;
            default   : accept;
        }
    }

    state parse_hula {
        packet.extract(hdr.hula);
        transition parse_srcRouting;
    }

    state parse_srcRouting {
        packet.extract(hdr.srcRoutes.next);
        transition select(hdr.srcRoutes.last.bos) {
            1       : parse_ipv4;
            default : parse_srcRouting;
        }
    }

    state parse_ipv4 {
        packet.extract(hdr.ipv4);
        transition select(hdr.ipv4.protocol) {
            8w17: parse_udp;
            default: accept;
        }
    }

    state parse_udp {
        packet.extract(hdr.udp);
        transition accept;
    }

}




control MyVerifyChecksum(inout headers hdr, inout metadata meta) {   
    apply {  }
}




control MyIngress(inout headers hdr,
                  inout metadata meta,
                  inout standard_metadata_t standard_metadata) {


    register<qdepth_t>(TOR_NUM) srcindex_qdepth_reg; 


    register<digest_t>(TOR_NUM) srcindex_digest_reg; 


/* At each hop, saves the next hop to reach each destination ToR */
    register<bit<16>>(TOR_NUM) dstindex_nhop_reg; 


/* At each hop saves the next hop for each flow */
    register<bit<16>>(65536) flow_port_reg; 


/* This action will drop packets */
    action drop() {
        mark_to_drop(standard_metadata);
    }

    action nop() {
    }

    action update_ttl(){
        hdr.ipv4.ttl = hdr.ipv4.ttl - 1;
    }

    action set_dmac(macAddr_t dstAddr){
        hdr.ethernet.srcAddr = hdr.ethernet.dstAddr;
        hdr.ethernet.dstAddr = dstAddr;
    }


/* This action just applies source routing */
    action srcRoute_nhop() {
        standard_metadata.egress_spec = (bit<9>)hdr.srcRoutes[0].port;
        hdr.srcRoutes.pop_front(1);
    }


    action hula_dst(bit<32> index) {
        meta.index = index;
    }


    action hula_set_nhop(bit<32> index) {
        dstindex_nhop_reg.write(index, (bit<16>)standard_metadata.ingress_port); 
    }


    action hula_get_nhop(bit<32> index){
       bit<16> tmp;
       dstindex_nhop_reg.read(tmp, index); 
       standard_metadata.egress_spec = (bit<9>)tmp;
    }


/* Record best path at destination ToR */
    action change_best_path_at_dst(){
        srcindex_qdepth_reg.write(meta.index, hdr.hula.qdepth);
        srcindex_digest_reg.write(meta.index, hdr.hula.digest);
    }


    action return_hula_to_src(){
        hdr.hula.dir = 1;
        standard_metadata.egress_spec = standard_metadata.ingress_port;
    }


    table hula_fwd {
        key = {
            hdr.ipv4.dstAddr: exact;
            hdr.ipv4.srcAddr: exact;
        }
        actions = {
            hula_dst;
            srcRoute_nhop;
        }
        default_action = srcRoute_nhop;
        size = TOR_NUM_1;

    }


    table hula_bwd {
        key = {
            hdr.ipv4.dstAddr: lpm;
        }
        actions = {
            hula_set_nhop;
        }
        size = TOR_NUM;
    }


    table hula_src {
        key = {
            hdr.ipv4.srcAddr: exact;
        }
        actions = {
            drop;
            srcRoute_nhop;
        }
        default_action = srcRoute_nhop;
        size = 2;
    }


/* Get nexthop based on dstAddr using registers */
    table hula_nhop {
        key = {
            hdr.ipv4.dstAddr: lpm;
        }
        actions = {
            hula_get_nhop;
            drop;
        }
        default_action = drop;
        size = TOR_NUM;
    }


/* Set right dmac for packets going to hosts */
    table dmac {
        key = {
            standard_metadata.egress_spec : exact;
        }
        actions = {
            set_dmac;
            nop;
        }
        default_action = nop;
        size = 16;
    }

    apply {
        if (hdr.hula.isValid()){
            if (hdr.hula.dir == 0){
                switch(hula_fwd.apply().action_run){


                    hula_dst: {


/* if it is the destination ToR compare qdepth */
                        qdepth_t old_qdepth;
                        srcindex_qdepth_reg.read(old_qdepth, meta.index);

                        if (old_qdepth > hdr.hula.qdepth){
                            change_best_path_at_dst();


/* only return hula packets that update best path */
                            return_hula_to_src();
                        }else{


                            digest_t old_digest;
                            srcindex_digest_reg.read(old_digest, meta.index);
                            if (old_digest == hdr.hula.digest){
                                srcindex_qdepth_reg.write(meta.index, hdr.hula.qdepth);
                            }

                            drop();
                        } 
                    }
                }
            }else {

/* update routing table in reverse path */
                hula_bwd.apply();


/* drop if source ToR */
                hula_src.apply();
            }
        } else if (hdr.ipv4.isValid()){
            bit<32> flow_hash;
            hash(
                flow_hash, 
                HashAlgorithm.crc16,
                32w0, 
                { hdr.ipv4.srcAddr, hdr.ipv4.dstAddr, hdr.udp.srcPort}, 
                32w65536
            );

            bit<16> port;
            flow_port_reg.read(port, flow_hash);

            if (port == 0) {

// next hop for destination ToR
                hula_nhop.apply();
                bit<16> next_hop = (bit<16>)standard_metadata.egress_spec;
                flow_port_reg.write(flow_hash, next_hop);
            } else {
                standard_metadata.egress_spec = (bit<9>)port;
            }


/* set the right dmac so that ping and iperf work */
            dmac.apply();
        }else {
            drop();
        }

        if (hdr.ipv4.isValid()){
            update_ttl();
        }
    }
}



control MyEgress(inout headers hdr,
                 inout metadata meta,
                 inout standard_metadata_t standard_metadata) {
    apply {

//hula header is valid and forward path
        if (hdr.hula.isValid() && hdr.hula.dir == 0) {

// hula qdepth greater than curr queue depth
            if (hdr.hula.qdepth < (qdepth_t)standard_metadata.deq_qdepth) {
                hdr.hula.qdepth = (qdepth_t)standard_metadata.deq_qdepth;
            }
        }
    }
}



control MyComputeChecksum(inout headers hdr, inout metadata meta) {
     apply {
	update_checksum(
	    hdr.ipv4.isValid(),
            { hdr.ipv4.version,
	      hdr.ipv4.ihl,
              hdr.ipv4.diffserv,
              hdr.ipv4.totalLen,
              hdr.ipv4.identification,
              hdr.ipv4.flags,
              hdr.ipv4.fragOffset,
              hdr.ipv4.ttl,
              hdr.ipv4.protocol,
              hdr.ipv4.srcAddr,
              hdr.ipv4.dstAddr },
            hdr.ipv4.hdrChecksum,
            HashAlgorithm.csum16);
    }
}




control MyDeparser(packet_out packet, in headers hdr) {
    apply {
        packet.emit(hdr.ethernet);
        packet.emit(hdr.hula);
        packet.emit(hdr.srcRoutes);
        packet.emit(hdr.ipv4);
        packet.emit(hdr.udp);
    }
}



V1Switch(
MyParser(),
MyVerifyChecksum(),
MyIngress(),
MyEgress(),
MyComputeChecksum(),
MyDeparser()
) main;

