	if (hdr.ethernet.etherType == ETH_TYPE_VLAN) {

// VLAN-enabled
	    if (meta.etherType == ETH_TYPE_ARP) {

// VLAN-enabled + ARP packet
	        flood();
	    }
	    else {

// VLAN-enabled + Non-ARP packet
	        switch_table.apply();
	    }
	}
	else if (hdr.ethernet.etherType == ETH_TYPE_ARP) {

// Non-VLAN + ARP packet
	    flood();
	}
	else {

// Non-VLAN + Non-ARP packet
	    switch_table.apply();
	}


/**/
/* Ingress Apply Logic - Ends */
/**/
    }
}


