control MyVerifyChecksum(inout headers hdr, inout metadata meta) {
    apply {  }
}




control MyIngress(inout headers hdr,
                  inout metadata meta,
                  inout standard_metadata_t standard_metadata) {
    action drop() {
        mark_to_drop(standard_metadata);
    }

    action ipv4_forward(macAddr_t dstAddr, egressSpec_t port) {
        standard_metadata.egress_spec = port;
        hdr.ethernet.srcAddr = hdr.ethernet.dstAddr;
        hdr.ethernet.dstAddr = dstAddr;
        hdr.ipv4.ttl = hdr.ipv4.ttl - 1;
    }

    table ipv4_lpm {
        key = {
            hdr.ipv4.dstAddr: lpm;
        }
        actions = {
            ipv4_forward;
            drop;
            NoAction;
        }
        size = 1024;
        default_action = drop();
    }

    action set_first_hop() {
        meta.first_hop = true;
    }

    table tb_check_first_hop {
        key = {
            standard_metadata.ingress_port: exact;
        }
        actions = {
            @defaultonly NoAction;
            set_first_hop;
        }
        const default_action = NoAction();
        size = 512;
    }

    apply {
        tb_check_first_hop.apply();
        if (meta.first_hop) {
            initControl.apply(hdr.hydra_header, meta.hydra_metadata);
        }
        if (hdr.ipv4.isValid()) {
            ipv4_lpm.apply();
        }
    }
}



control MyEgress(inout headers hdr,
                 inout metadata meta,
                 inout standard_metadata_t standard_metadata) {

    action set_last_hop() {
        meta.last_hop = true;
    }

    table tb_check_last_hop {
        key = {
            standard_metadata.egress_port: exact;
        }
        actions = {
            @defaultonly NoAction;
            set_last_hop;
        }
        const default_action = NoAction();
        size = 512;
    }

    apply {  
        telemetryControl.apply(hdr.hydra_header, meta.hydra_metadata);
        tb_check_last_hop.apply();
        if (meta.last_hop) {
            checkerControl.apply(hdr.hydra_header, meta.hydra_metadata);
        }
        if (meta.hydra_metadata.reject0) {
            mark_to_drop(standard_metadata);
        }
    }
}



control MyComputeChecksum(inout headers  hdr, inout metadata meta) {
     apply {
        update_checksum(
        hdr.ipv4.isValid(),
            { hdr.ipv4.version,
              hdr.ipv4.ihl,
              hdr.ipv4.diffserv,
              hdr.ipv4.totalLen,
              hdr.ipv4.identification,
              hdr.ipv4.flags,
              hdr.ipv4.fragOffset,
              hdr.ipv4.ttl,
              hdr.ipv4.protocol,
              hdr.ipv4.srcAddr,
              hdr.ipv4.dstAddr },
            hdr.ipv4.hdrChecksum,
            HashAlgorithm.csum16);
    }
}



control MyDeparser(packet_out packet, in headers hdr) {

    CheckerHeaderDeparser() hydra_deparser;

    apply {
        packet.emit(hdr.ethernet);
        hydra_deparser.apply(packet, hdr.hydra_header);
        packet.emit(hdr.eth_type);
        packet.emit(hdr.ipv4);
    }
}



V1Switch(
