        local_metadata.int_meta.source = true;
    }

    action int_set_sink () {
        local_metadata.int_meta.sink = true;
    }

    table tb_set_source {
        key = {
            standard_metadata.ingress_port: exact;
        }
        actions = {
            int_set_source;
            NoAction();
        }
        const default_action = NoAction();
        size = MAX_PORTS;
    }

    table tb_set_sink {
        key = {
            standard_metadata.egress_port: exact;   
        }
        actions = {
            int_set_sink;
            NoAction();
        }
        const default_action = NoAction();
        size = MAX_PORTS;
    }

    apply {
        tb_set_source.apply();
        tb_set_sink.apply();
    }
}


// Insert INT header to the packet
control process_int_source (
    inout headers hdr,
    inout local_metadata_t local_metadata) {

    action int_source(bit<5> hop_metadata_len, bit<8> remaining_hop_cnt, bit<4> ins_mask0003, bit<4> ins_mask0407) {

        hdr.intl4_shim.setValid();

// insert INT shim header
        hdr.intl4_shim.int_type = 1;

// INT type: MD-type (1) , destination type (2), MX-type (3)
        hdr.intl4_shim.npt = 0;

// next protocol type: 0
        hdr.intl4_shim.len = 3;

        hdr.intl4_shim.original_dscp = hdr.ipv4.dscp;

// original DSCP


// insert INT header
        hdr.int_header.setValid();
        hdr.int_header.ver = 2;

// INT 2.1
        hdr.int_header.d = 0;
        hdr.int_header.hop_metadata_len = hop_metadata_len;
        hdr.int_header.remaining_hop_cnt = remaining_hop_cnt;
        hdr.int_header.instruction_mask_0003 = ins_mask0003;
        hdr.int_header.instruction_mask_0407 = ins_mask0407;
        hdr.int_header.instruction_mask_0811 = 0;

// bit 8 is buffer related (not yet implemented), rest are reserved
        hdr.int_header.instruction_mask_1215 = 0;

// reserved

        hdr.int_header.domain_specific_id = 0;

// Unique INT Domain ID (not yet implemented)
        hdr.int_header.ds_instruction = 0;

// Instruction bitmap specific to the INT Domain identified by the Domain specific ID (not yet implemented)
        hdr.int_header.ds_flags = 0;

// Domain specific flags (not yet implemented)


// add the header len (3 words) to total len
        hdr.ipv4.len = hdr.ipv4.len + INT_TOTAL_HEADER_SIZE;
        if(hdr.udp.isValid()) {
            hdr.udp.length_ = hdr.udp.length_ + INT_TOTAL_HEADER_SIZE;
        }

        hdr.ipv4.dscp = DSCP_INT;
    }

    table tb_int_source {
        key = {

            hdr.ipv4.dst_addr: lpm;
        }
        actions = {
            int_source;
            NoAction;
        }
        const default_action = NoAction();
    }

    apply {
        tb_int_source.apply();
    }
}

control l3_forward(inout headers hdr,
                       inout local_metadata_t local_metadata,
                       inout standard_metadata_t standard_metadata) {

    action drop() {
        mark_to_drop(standard_metadata);
    }

    action ipv4_forward(mac_t dstAddr, mac_t srcAddr, port_t port) {
        standard_metadata.egress_spec = port;
        standard_metadata.egress_port = port;
        hdr.ethernet.src_addr = srcAddr;
        hdr.ethernet.dst_addr = dstAddr;
        hdr.ipv4.ttl = hdr.ipv4.ttl - 1;
    }   

    table ipv4_lpm {
        key = {
            hdr.ipv4.dst_addr : lpm;
        }
        actions = {
            ipv4_forward;
            drop;
        }
        size = 1024;
        const default_action = drop();
    }

    apply {
        if(hdr.ipv4.ttl == 0) {
            drop();
        }
        if(hdr.ipv4.isValid()) {
            ipv4_lpm.apply();
        }

    }
}




control MyIngress(inout headers hdr,
                  inout local_metadata_t local_metadata,
                  inout standard_metadata_t standard_metadata) {

    apply {
        if(hdr.ipv4.isValid()) {


// Perform L2 forwarding based on IPv4 destination address
            l3_forward.apply(hdr, local_metadata, standard_metadata);

            if (hdr.udp.isValid() || hdr.tcp.isValid()) {


// Setting source and sink local metadata
                process_int_source_sink.apply(hdr, local_metadata, standard_metadata);


// In case of source add the INT header
                if (local_metadata.int_meta.source == true) {
                    process_int_source.apply(hdr, local_metadata);
                }


// Clone packet for Telemetry Report
                if (local_metadata.int_meta.sink == true && hdr.int_header.isValid()) {
                    local_metadata.perserv_meta.ingress_port = standard_metadata.ingress_port;
                    local_metadata.perserv_meta.egress_port = standard_metadata.egress_port;
                    local_metadata.perserv_meta.deq_qdepth = standard_metadata.deq_qdepth;
                    local_metadata.perserv_meta.deq_timedelta = standard_metadata.deq_timedelta;
                    local_metadata.perserv_meta.ingress_global_timestamp = standard_metadata.ingress_global_timestamp;
                    local_metadata.perserv_meta.egress_global_timestamp = standard_metadata.egress_global_timestamp;
                    clone_preserving_field_list(CloneType.I2E, REPORT_MIRROR_SESSION_ID, 1);

                }
            }
        }
    }
}



control MyEgress(inout headers hdr,
                 inout local_metadata_t local_metadata,
                 inout standard_metadata_t standard_metadata) {

    apply {

// Insert old packet metadata into the cloned packet
        if(hdr.int_header.isValid() && standard_metadata.instance_type == CLONE_PKT) {
            standard_metadata.ingress_port = local_metadata.perserv_meta.ingress_port;
            standard_metadata.egress_port = local_metadata.perserv_meta.egress_port;
            standard_metadata.deq_qdepth = local_metadata.perserv_meta.deq_qdepth;
            standard_metadata.deq_timedelta = local_metadata.perserv_meta.deq_timedelta;
            standard_metadata.ingress_global_timestamp = local_metadata.perserv_meta.ingress_global_timestamp;
            standard_metadata.egress_global_timestamp = local_metadata.perserv_meta.egress_global_timestamp;
        }

        process_int_transit.apply(hdr, local_metadata, standard_metadata);


// In case of cloned packet, send telemetry report
        if (standard_metadata.instance_type == CLONE_PKT) {
            process_int_report.apply(hdr, local_metadata, standard_metadata);
        }


// In case of sink, remove INT header from original packet
        if (hdr.int_header.isValid() && local_metadata.int_meta.sink == true && standard_metadata.instance_type != CLONE_PKT) {
            process_int_sink.apply(hdr);
        }
    }
}



