#define DIMENSION 4

register<bit<32>>(20) register_pub_matrix;
register<bit<32>>(10) register_secret_vector;
register<bit<32>>(10) register_noise_vector;
register<bit<32>>(10) register_public_vector;
register<bit<32>>(36) register_public_vector_full;
register<bit<32>>(18) register_mod_public_vector;
register <bit<32>>(4) register_seed;


header ethernet_t {
    bit<48> dstAddr;
    bit<48> srcAddr;
    bit<16> etherType;
}


const bit<16> P4CALC_ETYPE = 0x1234;
const bit<8>  P4CALC_P     = 0x4B;

// K - KYBER
const bit<8>  GEN  = 0x47;

// 'G'
const bit<8>  ENC = 0x45;

// 'E'
const bit<8>  DEC   = 0x44;

// 'D'
const bit<32> PARAM_Q = 3329;

header p4calc_t {
    bit<8>  p;
    bit<8>  op;

    bit<32> t_0;
    bit<32> t_1;
    bit<32> t_2;
    bit<32> t_3;
    bit<32> t_4;
    bit<32> t_5;
    bit<32> t_6;
    bit<32> t_7;
    bit<32> t_8;
    bit<32> t_9;

    bit<32> seed;
}


struct headers {
    ethernet_t   ethernet;
    p4calc_t     p4calc;
}


struct metadata {

/* In our case it is empty */
}


parser MyParser(packet_in packet,
                out headers hdr,
                inout metadata meta,
                inout standard_metadata_t standard_metadata) {

    state start {
        packet.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType) {
            P4CALC_ETYPE : check_p4calc;
            default      : accept;
        }
    }

    state check_p4calc {
        transition select(packet.lookahead<p4calc_t>().p) {
            (P4CALC_P) : parse_p4calc;
            default    : accept;
        }
    }

    state parse_p4calc {
        packet.extract(hdr.p4calc);
        transition accept;
    }
}


control MyVerifyChecksum(inout headers hdr,
                         inout metadata meta) {
    apply { }
}


control MyIngress(inout headers hdr,
                  inout metadata meta,
                  inout standard_metadata_t standard_metadata) {

    action send_back() {
        bit<48> tmp;

        tmp = hdr.ethernet.dstAddr;
        hdr.ethernet.dstAddr = hdr.ethernet.srcAddr;
        hdr.ethernet.srcAddr = tmp;


/* Send the packet back to the port it came from */
        standard_metadata.egress_spec = standard_metadata.ingress_port;
    }

    #define gen_matrix(INDEX, ROUND) action gen_matrix_i##INDEX##_r##ROUND##() { \
        bit<32> coef;                                                            \
        register_seed.read(coef, 0);                                             \
        hash(coef, HashAlgorithm.crc32, (bit<32>) 0, {coef}, (bit<32>) PARAM_Q); \
        register_pub_matrix.write(##INDEX##, coef);                              \
        register_seed.write(0, coef);                                            \
    }
    gen_matrix(0, 1)
    gen_matrix(1, 1)
    gen_matrix(2, 1)
    gen_matrix(3, 1)
    gen_matrix(4, 1)
    gen_matrix(5, 1)
    gen_matrix(6, 1)
    gen_matrix(7, 1)
    gen_matrix(8, 1)
    gen_matrix(9, 1)
    gen_matrix(10, 1)
    gen_matrix(11, 1)
    gen_matrix(12, 1)
    gen_matrix(13, 1)
    gen_matrix(14, 1)
    gen_matrix(15, 1)
    gen_matrix(16, 1)
    gen_matrix(17, 1)
    gen_matrix(18, 1)
    gen_matrix(19, 1)


    #define gen_secret_vector(INDEX) action gen_secret_vector_i##INDEX##() { \
        bit<32> coef; \
        random(coef, 1, 4); \
        register_secret_vector.write(##INDEX##, coef); \
    }
    gen_secret_vector(0)
    gen_secret_vector(1)
    gen_secret_vector(2)
    gen_secret_vector(3)
    gen_secret_vector(4)
    gen_secret_vector(5)
    gen_secret_vector(6)
    gen_secret_vector(7)
