  }

  table round_tbl {
    key = {
    }
    actions = {
      round_tbl_action_0;
      round_tbl_action_1;
    }
  }


  apply {

// Pipeline
    if (!((hdr.ipv4.isValid() ? 1w1 : 1w0) == 1w1)) {
      if (!((hdr.paxos.isValid() ? 1w1 : 1w0) == 1w1)) {
        standard_metadata.egress_spec = 9w511;
