const bit<16> TYPE_SFC = 0x1212;

// Define TYPE for SFC
const bit<8> TYPE_TCP = 0x06;
const bit<8> TYPE_UDP = 0x11;
const bit<16> TYPE_IPV4 = 0x800;
const bit<16> TYPE_NSH = 0x894F;



typedef bit<9>  egressSpec_t;
typedef bit<48> macAddr_t;
typedef bit<32> ip4Addr_t;
typedef bit<16> tunnelAddr_t;

header ethernet_t {
    macAddr_t dstAddr;
    macAddr_t srcAddr;
    bit<16>   etherType;
}

header tunnel_t {
    tunnelAddr_t dst_id;

// Next SF
    tunnelAddr_t NxpHp_id;

// Next SFF/SF
}
header sfc_t {
    bit<2> ver;
    bit<1> zerobit;
    bit<1> u1;
    bit<6> ttl;
    bit<6> len;
    bit<4> u2;
    bit<4> MDtype;
    bit<8> protocol;
    bit<24> SPI;
    bit<8> SI;
    bit<128> context;
}

header ipv4_t {
    bit<4>    version;
    bit<4>    ihl;
    bit<8>    dscp;

// We use DSCP field to assign SFP
    bit<16>   totalLen;
    bit<16>   identification;
    bit<3>    flags;
    bit<13>   fragOffset;
    bit<8>    ttl;
    bit<8>    protocol;
    bit<16>   hdrChecksum;
    ip4Addr_t srcAddr;
    ip4Addr_t dstAddr;
}

header tcp_t {
    bit<16> srcPort;
    bit<16> dstPort;
    bit<32> seqNo;
    bit<32> ackNo;
    bit<4>  dataOffset;
    bit<3>  res;
    bit<3>  ecn;
    bit<6>  ctrl;
    bit<16> window;
    bit<16> checksum;
    bit<16> urgentPtr;
}

header udp_t {
    bit<16> srcPort;
    bit<16> dstPort;
    bit<16> len;
    bit<16> checksum;

}

struct metadata {

/* empty */
}

struct headers {
    ethernet_t ethernet;
    sfc_t sfc;
    ipv4_t ipv4;
    tcp_t tcp;
    udp_t udp;
}



parser MyParser(packet_in packet,
                out headers hdr,
                inout metadata meta,
                inout standard_metadata_t standard_metadata) {

    state start {
        transition parse_ethernet;
    }

    state parse_ethernet {
        packet.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType) {
            TYPE_NSH: parse_sfc;
            TYPE_IPV4: parse_ipv4;
            default: accept;
        }
    }
    state parse_sfc {
        packet.extract(hdr.sfc);
        transition parse_ipv4;
    }

    state parse_ipv4 {
        packet.extract(hdr.ipv4);
        transition select(hdr.ipv4.protocol) {
            TYPE_TCP: parse_tcp;
            TYPE_UDP: parse_udp;
            default: accept;
        }
    }

    state parse_tcp {
        packet.extract(hdr.tcp);
        transition accept;
    }
    state parse_udp {
        packet.extract(hdr.udp);
        transition accept;
    }
}



control MyVerifyChecksum(inout headers hdr, inout metadata meta) {
    apply {  }
}




control MyIngress(inout headers hdr,
                  inout metadata meta,
                  inout standard_metadata_t standard_metadata) {
    action drop() {
        mark_to_drop(standard_metadata);
    }
    action ipv4_forward(macAddr_t dstAddr, egressSpec_t port) {
        standard_metadata.egress_spec = port;
        hdr.ethernet.srcAddr = hdr.ethernet.dstAddr;
        hdr.ethernet.dstAddr = dstAddr;
        hdr.ipv4.ttl = hdr.ipv4.ttl - 1;
    }

    table ipv4_lpm {
        key = {
            hdr.ipv4.dstAddr: lpm;
        }
        actions = {
            ipv4_forward;
            drop;
            NoAction;
        }
        size = 1024;
        default_action = drop();
    }

    action sfc_decapsulation() {
           hdr.ethernet.etherType = TYPE_IPV4;
           hdr.ipv4.dscp = 0;
           hdr.sfc.setInvalid();
    }
    table sfc_termination {
        key = {
            hdr.ethernet.dstAddr: exact;
        }
        actions = {
            sfc_decapsulation;
            NoAction;
        }
        size = 1024;
        default_action = NoAction();
    }
    action sfc_encapsulation(bit<24> SPI) {
        hdr.ethernet.etherType = TYPE_NSH;
        hdr.sfc.setValid();
        hdr.sfc.ver = 0x1;

        hdr.sfc.zerobit = 0;
        hdr.sfc.u1 = 0;
        hdr.sfc.ttl = 63;
        hdr.sfc.len = 0x6;
        hdr.sfc.u2 = 0;
        hdr.sfc.MDtype = 0x1;

// Fixed sized
        hdr.sfc.protocol = 0x1;

        hdr.sfc.SPI = SPI;
        hdr.sfc.SI = 255;
    }
    table sfc_classifier {
        key = {
            hdr.ipv4.dscp: exact;
        }
        actions = {
            sfc_encapsulation;
            NoAction;
        }
        size = 1024;
        default_action = NoAction();
    }

    action sfc_forward(macAddr_t dstAddr, egressSpec_t port) {
        standard_metadata.egress_spec = port;
        hdr.ethernet.srcAddr = hdr.ethernet.dstAddr;
        hdr.ethernet.dstAddr = dstAddr;
        hdr.ipv4.ttl = hdr.ipv4.ttl - 1;
    }

    table sfc_egress {
        key = {
            hdr.sfc.SPI: exact;
            hdr.sfc.SI: exact;
        }
        actions = {
            sfc_forward;
            NoAction;
            drop;
        }
        size = 1024;
        default_action = drop();
    }


    apply {
        if (hdr.ipv4.isValid() && hdr.ipv4.dscp == 0) {

// Process only non-SFC packets
            ipv4_lpm.apply();
        }
        else{
            if (!hdr.sfc.isValid()){
                sfc_classifier.apply();
            }
            else{
                hdr.sfc.ttl = hdr.sfc.ttl - 1;
                hdr.sfc.SI = hdr.sfc.SI - 1;
            }
            if (hdr.sfc.SI == 0 || hdr.sfc.ttl == 0){
                drop();
            }
            sfc_egress.apply();
            sfc_termination.apply();
        }
    }
}



control MyEgress(inout headers hdr,
                 inout metadata meta,
                 inout standard_metadata_t standard_metadata) {
    apply {  }
}



control MyComputeChecksum(inout headers  hdr, inout metadata meta) {
     apply {
	update_checksum(
	    hdr.ipv4.isValid(),
            { hdr.ipv4.version,
	      hdr.ipv4.ihl,
              hdr.ipv4.dscp,
              hdr.ipv4.totalLen,
              hdr.ipv4.identification,
              hdr.ipv4.flags,
              hdr.ipv4.fragOffset,
              hdr.ipv4.ttl,
              hdr.ipv4.protocol,
              hdr.ipv4.srcAddr,
              hdr.ipv4.dstAddr },
            hdr.ipv4.hdrChecksum,
            HashAlgorithm.csum16);
    }
}



control MyDeparser(packet_out packet, in headers hdr) {
    apply {
        packet.emit(hdr.ethernet);
        packet.emit(hdr.sfc);
        packet.emit(hdr.ipv4);
        packet.emit(hdr.tcp);
        packet.emit(hdr.udp);
    }
}



V1Switch(
MyParser(),
MyVerifyChecksum(),
MyIngress(),
MyEgress(),
MyComputeChecksum(),
MyDeparser()
) main;

