    bit<16>   totalLen;
    bit<16>   identification;
    bit<3>    flags;
    bit<13>   fragOffset;
    bit<8>    ttl;
    bit<8>    protocol;
    bit<16>   hdrChecksum;
    ip4Addr_t srcAddr;
    ip4Addr_t dstAddr;
}

struct metadata {
}

struct headers {
    ethernet_t   ethernet;
    ipv4_t       ipv4;
}



parser MyParser(packet_in packet,
                  out headers hdr,
                  inout metadata meta,
                  inout standard_metadata_t standard_metadata) {

    state start {
        transition parse_ethernet;
    }

    state parse_ethernet {
        packet.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType) {
            TYPE_IPV4: parse_ipv4;
            default: accept;
        }
    }

    state parse_ipv4 {
        packet.extract(hdr.ipv4);
        transition accept;
    }
}




control MyVerifyChecksum(inout headers hdr, inout metadata meta) {
    apply {  }
}




control MyIngress(inout headers hdr,
                  inout metadata meta,
                  inout standard_metadata_t standard_metadata) {



    action drop() {
        mark_to_drop(standard_metadata);
    }

    action ipv4_forward(macAddr_t dstAddr, egressSpec_t port) {
        standard_metadata.egress_spec = port;
        hdr.ethernet.srcAddr = hdr.ethernet.dstAddr;
        hdr.ethernet.dstAddr = dstAddr;
        hdr.ipv4.ttl = hdr.ipv4.ttl - 1;
    }

    table ipv4_lpm {
        key = {
            hdr.ipv4.dstAddr: lpm;
        }
        actions = {
            ipv4_forward;
            drop;
        }
        size = 1024;
        default_action = drop;
    }

    apply {
        if (hdr.ipv4.isValid()) {

            ipv4_lpm.apply();
        }
    }
}



control MyEgress(inout headers hdr,
                 inout metadata meta,
                 inout standard_metadata_t standard_metadata) {

     action drop() {
         mark_to_drop(standard_metadata);
     }

    register<bit<19>>(REGISTER_LENGTH) avg_r;
    register<bit<11>>(1) dp_r;

    apply {




        bit<32>reg_pos_zero = 0;
        bit<19> queue_size_now = standard_metadata.enq_qdepth;
        bit<19> Old_AVG;
        avg_r.read(Old_AVG,reg_pos_zero);
        bit<19> new_AVG = (Old_AVG*98)+(queue_size_now*2);
        avg_r.write(reg_pos_zero,new_AVG);


        if (new_AVG > MinTh && new_AVG < MaxTh) {
            bit<32> pos_zero = 0;
            bit<11> drop_prob_read = 0;
            dp_r.read(drop_prob_read,pos_zero);
            if (drop_prob_read == 0){
                drop_prob_read = 1;
            };
            bit<11> drop_prob_write = drop_prob_read * 2;
            dp_r.write(pos_zero,drop_prob_write);
            bit<11> rand_val;
            random<bit<11>>(rand_val, 0, 16);
            if (drop_prob_write > rand_val){
                drop();
            }
        }

        if (new_AVG > MaxTh) {
            drop();
        }




    }
}



control MyComputeChecksum(inout headers hdr, inout metadata meta) {
    apply {

	update_checksum(
	    hdr.ipv4.isValid(),
            { hdr.ipv4.version,
              hdr.ipv4.ihl,
              hdr.ipv4.diffserv,
              hdr.ipv4.ecn,
              hdr.ipv4.totalLen,
              hdr.ipv4.identification,
              hdr.ipv4.flags,
              hdr.ipv4.fragOffset,
              hdr.ipv4.ttl,
              hdr.ipv4.protocol,
              hdr.ipv4.srcAddr,
              hdr.ipv4.dstAddr },
            hdr.ipv4.hdrChecksum,
            HashAlgorithm.csum16);
    }
}



control MyDeparser(packet_out packet, in headers hdr) {
    apply {
        packet.emit(hdr.ethernet);
        packet.emit(hdr.ipv4);
    }
}



V1Switch(
MyParser(),
MyVerifyChecksum(),
MyIngress(),
MyEgress(),
MyComputeChecksum(),
MyDeparser()
) main;

