    bit<64> preamble;
    bit<8>  device;
    bit<8>  reason;
    bit<8>  if_index;
}

header ethernet_t {
    bit<48>   dstAddr;
    bit<48>   srcAddr;
    bit<16>   etherType;
}

header ipv4_t {
    bit<4>    version;
    bit<4>    ihl;
    bit<8>    diffserv;
    bit<16>   totalLen;
    bit<16>   identification;
    bit<3>    flags;
    bit<13>   fragOffset;
    bit<8>    ttl;
    bit<8>    protocol;
    bit<16>   hdrChecksum;
    bit<32>   srcAddr;
    bit<32>   dstAddr;
}

header vxlan_t  {
	bit<8> flags;
	bit<24> reserved1;
	bit<24> vni;
	bit<8> reserved2;

}

header icmp_t {
    bit<8>  type;
    bit<8>  code;
    bit<16> checksum;
}


header gtp_t {
        bit<3> version; /* this should be 1 for GTPv1 and 2 for GTPv2 */
        bit<1> pFlag;   /* protocolType for GTPv1 and pFlag for GTPv2 */
	    bit<1> reserved;

        bit<1> eFlag;   /* only used by GTPv1 - E flag */
        bit<1> sFlag;   /* only used by GTPv1 - S flag */
        bit<1> pnFlag;  /* only used by GTPv1 - PN flag */
	    bit<8> messageType;
        bit<16> messageLength;
	    bit<32> teid;

}




