}

struct metadata_t {
    fwd_metadata_t fwd_metadata;
}

struct headers_t {
    ethernet_t ethernet;
    ipv4_t     ipv4;
}

parser parserImpl(packet_in packet,
                  out headers_t hdr,
                  inout metadata_t meta,
                  inout standard_metadata_t stdmeta)
{
    const bit<16> ETHERTYPE_IPV4 = 0x0800;

    state start {
        transition parse_ethernet;
    }
    state parse_ethernet {
        packet.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType) {
            ETHERTYPE_IPV4: parse_ipv4;
            default: accept;
        }
    }
    state parse_ipv4 {
        packet.extract(hdr.ipv4);
        transition accept;
    }
}

control ingressImpl(inout headers_t hdr,
                    inout metadata_t meta,
                    inout standard_metadata_t stdmeta)
{
    action my_drop() {
        mark_to_drop(stdmeta);

// Skip the rest of ingress processing.
        exit;
    }

    action set_mcast_grp (bit<16> mcast_grp) {
        stdmeta.mcast_grp = mcast_grp;

// See Section 6.4 of RFC 1112
        hdr.ethernet.dstAddr = (24w0x01005E ++
            ((bit<24>) hdr.ipv4.dstAddr[22:0]));

        hdr.ipv4.ttl = hdr.ipv4.ttl |-| 1;
    }
    table ipv4_mc_route_lookup {
        key = {
            hdr.ipv4.dstAddr: lpm;
        }
        actions = {
            set_mcast_grp;
            my_drop;
        }
        const default_action = my_drop;
    }

    action set_l2ptr(bit<32> l2ptr) {
        meta.fwd_metadata.l2ptr = l2ptr;
    }
    table ipv4_da_lpm {
        key = {
            hdr.ipv4.dstAddr: lpm;
        }
        actions = {
            set_l2ptr;
            my_drop;
        }
        const default_action = my_drop;
    }

    action set_dmac_intf(bit<48> dmac, bit<9> intf) {
        hdr.ethernet.dstAddr = dmac;
        stdmeta.egress_spec = intf;
        hdr.ipv4.ttl = hdr.ipv4.ttl |-| 1;
    }
    table mac_da {
        key = {
            meta.fwd_metadata.l2ptr: exact;
        }
        actions = {
            set_dmac_intf;
            my_drop;
        }
        const default_action = my_drop;
    }

    apply {
        if (hdr.ipv4.isValid()) {

            if (hdr.ipv4.dstAddr[31:28] == 0xe) {

                ipv4_mc_route_lookup.apply();
            } else {
                ipv4_da_lpm.apply();
                mac_da.apply();
            }
            if (hdr.ipv4.ttl == 0) {

                my_drop();
            }
        } else {

            my_drop();
        }
    }
}

control egressImpl(inout headers_t hdr,
                   inout metadata_t meta,
                   inout standard_metadata_t stdmeta)
{
    table dbg1 {
        key = {
            stdmeta.egress_port: exact;
            stdmeta.egress_rid: exact;
        }
        actions = { NoAction; }
        const default_action = NoAction;
    }
    action my_drop() {
        mark_to_drop(stdmeta);

// Skip the rest of ingress processing.
        exit;
    }

    action rewrite_mac(bit<48> smac) {
        hdr.ethernet.srcAddr = smac;
    }
    table send_frame {
        key = {
            stdmeta.egress_port: exact;
        }
        actions = {
            rewrite_mac;
            my_drop;
        }
        const default_action = my_drop;
    }

    apply {

        dbg1.apply();

        send_frame.apply();
    }
}

