   bit<1>  urg;
   bit<1>  ack;
   bit<1>  psh;
   bit<1>  rst;
   bit<1>  syn;
   bit<1>  fin;
   bit<16> window;
   bit<16> checksum;
   bit<16> urgentPtr;
}

#define MAX_TCP_OPTION_WORD 10
header tcp_option_t{
   bit<32> data;
}


struct metadata {

/* empty */
}

struct headers {
   ethernet_t  ethernet;
   ipv4_t      ipv4;
   tcp_t       tcp;
   tcp_option_t[MAX_TCP_OPTION_WORD] tcp_opt;
}



parser MyParser(packet_in packet,
      out headers hdr,
      inout metadata meta,
      inout standard_metadata_t standard_metadata) {
   bit<4> tcp_opt_cnt = 0;
   state start {
      transition select(standard_metadata.ingress_port) {
          2: parse_ethernet;

// port 2: Ethernet
          1: parse_ipv4;

// port 1: IP (TUN)
      }
   }

   state parse_ethernet {
      packet.extract(hdr.ethernet);
      transition select(hdr.ethernet.etherType) {
         0x800  : parse_ipv4;
         default: accept;
      }
   }
   state parse_ipv4 {
      packet.extract(hdr.ipv4);
      transition select(hdr.ipv4.protocol){
         0x006  : parse_tcp;
         default: accept;
      }
   }

   state parse_tcp {
      packet.extract(hdr.tcp);


//HN: jump over TCP options
      tcp_opt_cnt = hdr.tcp.dataOffset;

      if( tcp_opt_cnt > 5 )
         tcp_opt_cnt = tcp_opt_cnt - 5;
      else
         tcp_opt_cnt = 0;

      transition select( tcp_opt_cnt ){
         default : parse_tcp_option;
      }
   }

   state parse_tcp_option {
      packet.extract( hdr.tcp_opt.next );
      tcp_opt_cnt = tcp_opt_cnt - 1;
      transition select( tcp_opt_cnt ){
         default: parse_tcp_option;
      }
   }
}



control MyVerifyChecksum(inout headers hdr, inout metadata meta) {
   apply {  }
}




control MyIngress(inout headers hdr,
      inout metadata meta,
      inout standard_metadata_t standard_metadata) {

   apply {
      log_msg("new packet comming from port = {}", {standard_metadata.ingress_port});

      if ( standard_metadata.ingress_port ==  1 ){
        standard_metadata.egress_spec = 2;
      } else {
        standard_metadata.egress_spec = 1;
        log_msg("mac_src: {}, mac_dst: {}", {hdr.ethernet.srcAddr, hdr.ethernet.dstAddr});

//drop broadcast
        if(hdr.ethernet.dstAddr != 1 && hdr.ethernet.dstAddr != 2 ){
          log_msg(" ==> dopped broadcast packet");
          mark_to_drop(standard_metadata);
          return;
        }
      }
      log_msg("ip_src: {}, ip_dst: {}", {hdr.ipv4.srcAddr, hdr.ipv4.dstAddr} );


      if( hdr.tcp.rst == 1 && hdr.ipv4.srcAddr == 170721290 ){
         log_msg( " ==> drop reset");
         mark_to_drop(standard_metadata);
      }

   }
}



control MyEgress(inout headers hdr,
      inout metadata meta,
      inout standard_metadata_t standard_metadata) {
   apply {

      if ( standard_metadata.egress_port ==  2 ){
        hdr.ethernet.setValid();
        hdr.ethernet.srcAddr = 1;

// src & dst MAC are fixed
        hdr.ethernet.dstAddr = 2;
        hdr.ethernet.etherType = 0x800;

      } else {

        hdr.ethernet.setInvalid();
      }
   }
}



control MyComputeChecksum(inout headers  hdr, inout metadata meta) {
   apply {
      update_checksum(
            hdr.ipv4.isValid(),
            { hdr.ipv4.version,
            hdr.ipv4.ihl,
            hdr.ipv4.dscp,
            hdr.ipv4.ecn,
            hdr.ipv4.totalLen,
            hdr.ipv4.identification,
            hdr.ipv4.flags,
            hdr.ipv4.fragOffset,
            hdr.ipv4.ttl,
            hdr.ipv4.protocol,
            hdr.ipv4.srcAddr,
            hdr.ipv4.dstAddr },
            hdr.ipv4.hdrChecksum,
            HashAlgorithm.csum16);
   }
}



control MyDeparser(packet_out packet, in headers hdr) {
   apply {
      packet.emit(hdr.ethernet);
      packet.emit(hdr.ipv4);
      packet.emit(hdr.tcp);
      packet.emit(hdr.tcp_opt);
   }
}



V1Switch(
   MyParser(),
   MyVerifyChecksum(),
   MyIngress(),
   MyEgress(),
   MyComputeChecksum(),
   MyDeparser()
) main;

