header ethernet_t {
    bit<48> dstAddr;
    bit<48> srcAddr;
    bit<16> etherType;
}


const bit<16> P4CALC_ETYPE = 0x1234;
const bit<8>  P4CALC_P     = 0x50;

// 'P'
const bit<8>  P4CALC_4     = 0x34;

// '4'
const bit<8>  P4CALC_VER   = 0x01;

// v0.1
const bit<8>  P4CALC_PLUS  = 0x2b;

// '+'
const bit<8>  P4CALC_MINUS = 0x2d;

// '-'
const bit<8>  P4CALC_AND   = 0x26;

// '&'
const bit<8>  P4CALC_OR    = 0x7c;

// '|'
const bit<8>  P4CALC_CARET = 0x5e;


header p4scramb_t {
    bit<8> p;
    bit<8> four;
    bit<8> ver;
    bit<32>  secret;
}


struct headers {
    ethernet_t   ethernet;
    p4scramb_t     p4scramb;
}



struct metadata {

/* In our case it is empty */
}


parser MyParser(packet_in packet,
                out headers hdr,
                inout metadata meta,
                inout standard_metadata_t standard_metadata) {
    state start {
        packet.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType) {
            P4CALC_ETYPE : check_p4scramb;
            default      : accept;
        }
    }

    state check_p4scramb {

        transition select(packet.lookahead<p4scramb_t>().p,
        packet.lookahead<p4scramb_t>().four) {
            (P4CALC_P, P4CALC_4) : parse_p4scramb;
            default              : accept;
        }

    }

    state parse_p4scramb {
        packet.extract(hdr.p4scramb);
        transition accept;
    }
}


control MyVerifyChecksum(inout headers hdr,
                         inout metadata meta) {
    apply { }
}


control MyIngress(inout headers hdr,
                  inout metadata meta,
                  inout standard_metadata_t standard_metadata) {
    action send_back(bit<32> sec) {

         hdr.p4scramb.secret = sec;
         bit<48> temp;

         temp = hdr.ethernet.dstAddr;
         hdr.ethernet.dstAddr = hdr.ethernet.srcAddr;
         hdr.ethernet.srcAddr = temp; 

         standard_metadata.egress_spec = standard_metadata.ingress_port;
    }

    action operation_drop() {
        mark_to_drop(standard_metadata);
    }

    action simple_xor(bit<32> my_key) {
        bit<32> my_msg;
        my_msg = hdr.p4scramb.secret ^ my_key;
        send_back(my_msg);
    }

    action caesar(bit<32> my_key){
        send_back(hdr.p4scramb.secret + my_key);
    }

    action left_right(bit<32> secret_key){
		bit<32> left = hdr.p4scramb.secret >> 16;
		bit<32> right = hdr.p4scramb.secret & (bit<32>) 65535;

		bit<32> new_left = right;
		bit<32> new_right = left ^ secret_key ^ right;

		right = new_right;
		left = new_right ^ new_left ^ (bit<32>) 0xDEADBABE;

		send_back((left << 16) | right);


	}

    table scramble {
        key = {
            hdr.p4scramb.ver        : exact;
        }
        actions = {

            left_right;
            simple_xor;
            caesar;
            operation_drop;
        }

        const default_action = operation_drop();

    }

    apply {
        if (hdr.ethernet.isValid()) {
            scramble.apply();
        } else {
            operation_drop();
        }
    }
}


control MyEgress(inout headers hdr,
                 inout metadata meta,
                 inout standard_metadata_t standard_metadata) {
    apply { }
}



control MyComputeChecksum(inout headers hdr, inout metadata meta) {
    apply { }
}


control MyDeparser(packet_out packet, in headers hdr) {
    apply {
        packet.emit(hdr.ethernet);
        packet.emit(hdr.p4scramb);
    }
}



