typedef bit<48> EthernetAddress;
typedef bit<32> IPv4Address;


// Ethernet header definition
header ethernet_t {
    EthernetAddress dst_addr;
    EthernetAddress src_addr;
    bit<16>         ether_type;
}


// IPv4 header definition
header ipv4_t {
    bit<4>      version;
    bit<4>      ihl;
    bit<8>      diffserv;
    bit<16>     total_len;
    bit<16>     identification;
    bit<3>      flags;
    bit<13>     frag_offset;
    bit<8>      ttl;
    bit<8>      protocol;
    bit<16>     hdr_checksum;
    IPv4Address src_addr;
    IPv4Address dst_addr;
}


// Structure combining Ethernet and IPv4 headers
struct headers_t {
    ethernet_t ethernet;
    ipv4_t     ipv4;
}


// Empty metadata structure
struct metadata_t {
}


// Enumerates possible errors related to IPv4 processing
error {
    IPv4IncorrectVersion,
    IPv4OptionsNotSupported
}


// Parser for Ethernet and IPv4 headers
parser MyParser(packet_in packet,
                out headers_t hd,
                inout metadata_t meta,
                inout standard_metadata_t standard_meta) {
    state start {

// Extract Ethernet header
        packet.extract(hd.ethernet);

// Transition based on EtherType
        transition select(hd.ethernet.ether_type) {
            0x0800:  parse_ipv4;

// If IPv4, go to IPv4 parsing
            default: accept;

// Otherwise, accept the packet
        }
    }

    state parse_ipv4 {

// Extract IPv4 header
        packet.extract(hd.ipv4);

// Verify IPv4 version and IHL
        verify(hd.ipv4.version == 4w4, error.IPv4IncorrectVersion);
        verify(hd.ipv4.ihl == 4w5, error.IPv4OptionsNotSupported);

// Move to the accept state after successful parsing
        transition accept;
    }    
}


// Custom deparser to emit Ethernet and IPv4 headers
control MyDeparser(packet_out packet,
                   in headers_t hdr) {
    apply {

// Emit Ethernet header
        packet.emit(hdr.ethernet);

// Emit IPv4 header
        packet.emit(hdr.ipv4);
    }
}


