header ethernet_t {
    bit<48> dstAddr;
    bit<48> srcAddr;
    bit<16> etherType;
}


header ipv4_t {
    bit<4>       version;
    bit<4>       ihl;
    bit<8>       diffserv;
    bit<16>      totalLen;
    bit<16>      identification;
    bit<3>       flags;
    bit<13>      fragOffset;
    bit<8>       ttl;
    bit<8>       protocol;
    bit<16>      hdrChecksum;
    IPv4Address  srcAddr;
    IPv4Address  dstAddr;
    varbit<320>  options;
}

header tcp_t {
    bit<16> srcPort;
    bit<16> dstPort;
    bit<32> seqNo;
    bit<32> ackNo;
    bit<4>  dataOffset;
    bit<3>  res;
    bit<3>  ecn;
    bit<6>  ctrl;
    bit<16> window;
    bit<16> checksum;

    bit<16> urgentPtr;
    varbit<320>  options;
}

header udp_t {
    bit<16> srcPort;
    bit<16> dstPort;
    bit<16> length_;
    bit<16> checksum;
}

header IPv4_up_to_ihl_only_h {
    bit<4>       version;
    bit<4>       ihl;
}

header tcp_upto_data_offset_only_h {
    bit<16> srcPort;
    bit<16> dstPort;
    bit<32> seqNo;
    bit<32> ackNo;

    bit<4>  dataOffset;
    bit<4>  dontCare;
}

struct headers {
    ethernet_t           ethernet;
    ipv4_t               ipv4;
    tcp_t                tcp;
    udp_t                udp;
}

struct mystruct1_t {
    bit<4>  a;
    bit<4>  b;
}

struct metadata {
    mystruct1_t mystruct1;
    bit<16>     l4Len;

}

typedef tuple<
    bit<4>,
    bit<4>,
    bit<8>,
    varbit<56>
    > myTuple1;


// Declare user-defined errors that may be signaled during parsing
error {
    IPv4HeaderTooShort,
    TCPHeaderTooShort,
    IPv4IncorrectVersion,
    IPv4ChecksumError
}

parser parserI(packet_in pkt,
               out headers hdr,
               inout metadata meta,
               inout standard_metadata_t stdmeta)
{
    state start {
        pkt.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType) {
            0x0800: parse_ipv4;
            default: accept;
        }
    }
    state parse_ipv4 {

        pkt.extract(hdr.ipv4,
                    (bit<32>)
                    (8 *
                     (4 * (bit<9>) (pkt.lookahead<IPv4_up_to_ihl_only_h>().ihl)
                      - 20)));
        verify(hdr.ipv4.version == 4w4, error.IPv4IncorrectVersion);
        verify(hdr.ipv4.ihl >= 4w5, error.IPv4HeaderTooShort);
        meta.l4Len = hdr.ipv4.totalLen - (bit<16>)(hdr.ipv4.ihl)*4;
        transition select (hdr.ipv4.protocol) {
            6: parse_tcp;
            17: parse_udp;
            default: accept;
        }
    }
    state parse_tcp {

        pkt.extract(hdr.tcp,
                    (bit<32>)
                    (8 *
                     (4 * (bit<9>) (pkt.lookahead<tcp_upto_data_offset_only_h>().dataOffset)
                      - 20)));
        verify(hdr.tcp.dataOffset >= 4w5, error.TCPHeaderTooShort);
        transition accept;
    }
    state parse_udp {
        pkt.extract(hdr.udp);
        transition accept;
    }

}

control cIngress(inout headers hdr,
                 inout metadata meta,
                 inout standard_metadata_t stdmeta)
{
    action client_send(bit<48> src_mac, bit<48> dst_mac, bit<32> src_ip, bit<9> port){
        hdr.ethernet.srcAddr=src_mac;
        hdr.ethernet.dstAddr=dst_mac;
        hdr.ipv4.srcAddr=src_ip;
        stdmeta.egress_spec = port;

    }
    action server_recieve(bit<48> src_mac, bit<48> dst_mac, bit<32> dst_ip, bit<9> port){
        hdr.ethernet.srcAddr=src_mac;
        hdr.ethernet.dstAddr=dst_mac;
        hdr.ipv4.dstAddr=dst_ip;
        stdmeta.egress_spec = port;

    }
    action server_send(bit<48> src_mac, bit<48> dst_mac, bit<32> src_ip, bit<9> port){
        hdr.ethernet.srcAddr=src_mac;
        hdr.ethernet.dstAddr=dst_mac;
        hdr.ipv4.srcAddr=src_ip;
        stdmeta.egress_spec = port;

    }
    action client_recieve(bit<48> src_mac, bit<48> dst_mac, bit<32> dst_ip, bit<9> port){
        hdr.ethernet.srcAddr=src_mac;
        hdr.ethernet.dstAddr=dst_mac;
        hdr.ipv4.dstAddr=dst_ip;
        stdmeta.egress_spec = port;

    }
    action foot() {
        hdr.tcp.srcPort = hdr.tcp.srcPort + 1;
        hdr.ipv4.ttl = hdr.ipv4.ttl - 1;
        hdr.ipv4.dstAddr = hdr.ipv4.dstAddr + 4;
    }
    action foou() {
        hdr.udp.srcPort = hdr.udp.srcPort + 1;
        hdr.ipv4.ttl = hdr.ipv4.ttl - 1;
        hdr.ipv4.dstAddr = hdr.ipv4.dstAddr + 4;
    }
    action to_port_action(bit<48> dst_mac,bit<32> dst_ip, bit<32> src_ip, bit<9> port){

        hdr.ethernet.dstAddr=dst_mac;
        hdr.ipv4.dstAddr=dst_ip;
        hdr.ipv4.srcAddr=src_ip;
        stdmeta.egress_spec = port;
    }
    action send_to_nat(bit<48> src_mac,bit<48> dst_mac,bit<32> src_ip, bit<32> dst_ip, bit<9> port){
        hdr.ethernet.srcAddr=src_mac;
        hdr.ethernet.dstAddr=dst_mac;
        hdr.ipv4.dstAddr=dst_ip;
        hdr.ipv4.srcAddr=src_ip;
        stdmeta.egress_spec = port;

    }
    table client_send_t {
        key = {
	    hdr.tcp.dstPort :exact; 
        }
        actions = {client_send;NoAction; }
        default_action = NoAction;
    }
    table server_recieve_t {
        key = {
	    hdr.tcp.dstPort :exact;
            hdr.ipv4.srcAddr: exact;

        }
        actions = {server_recieve;NoAction; }
        default_action = NoAction;
    }
    table server_send_t {
        key = {
	    hdr.tcp.srcPort :exact;

        }
        actions = {server_send;NoAction; }
        default_action = NoAction;
    }
    table client_recieve_t {
        key = {
	    hdr.tcp.srcPort :exact;
	    hdr.ipv4.srcAddr: exact;

        }
        actions = {client_recieve;NoAction; }
        default_action = NoAction;
    }

    table ipv4_match {
        key = {
            hdr.ipv4.dstAddr : lpm;
        }
        actions = {to_port_action;NoAction; }
        default_action = NoAction;
    }

    table ipv4_src_match {
        key = {
            hdr.ipv4.srcAddr : exact;
        }
        actions = {to_port_action;NoAction; }
        default_action = NoAction;
    }

    table guh {
        key = {
            hdr.tcp.dstPort : exact;
        }
        actions = { foot; NoAction; }
        const default_action = NoAction;

        const entries = {
            (16w80) : foot();
        }
    }
    table huh {
        key = {
            hdr.udp.dstPort : exact;
        }
        actions = { foou; NoAction; }
        const default_action = NoAction;

        const entries = {
            (16w80) : foou();
        }
    }
    apply {

            server_recieve_t.apply();

    }
}

