#include <core.p4>
#include <v1model.p4>


const bit<16> ETH_TYPE_IPV4 = 0x0800;
const bit<8>  IP_PROTO_UDP  = 17;


typedef bit<48> mac_addr_t;
typedef bit<32> ipv4_addr_t;


header ethernet_t { mac_addr_t dst; mac_addr_t src; bit<16> eth_type; }

header ipv4_t {
    bit<4>  version;
    bit<4>  ihl;
    bit<6>  dscp;
    bit<2>  ecn;
    bit<16> totalLen;
    bit<16> identification;
    bit<3>  flags;
    bit<13> fragOffset;
    bit<8>  ttl;
    bit<8>  protocol;
    bit<16> hdrChecksum;
    ipv4_addr_t srcAddr;
    ipv4_addr_t dstAddr;
}

header udp_t { bit<16> srcPort; bit<16> dstPort; bit<16> len; bit<16> checksum; }


struct my_md_t {
    bit<3> qos_class;
    bit<3> queue_id;
    bit<8> input_vector;
}


struct headers_t { ethernet_t eth; ipv4_t ip4; udp_t udp; }


register<bit<8>>(6) bnn_weights;


bit<4> popcnt8(in bit<8> v) {
    bit<8> t;
    t = v - ((v >> 1) & (bit<8>)0x55);
    t = ((t >> 2) & (bit<8>)0x33) + (t & (bit<8>)0x33);
    t = ((t >> 4) + t) & (bit<8>)0x0F;
    return (bit<4>) t;
}


/*  Parser  */
parser MyParser(packet_in packet,
                out headers_t hdr,
                inout my_md_t md,
                inout standard_metadata_t sm) {

    state start { transition parse_ethernet; }

    state parse_ethernet {
        packet.extract(hdr.eth);
        transition select(hdr.eth.eth_type) {
            ETH_TYPE_IPV4: parse_ipv4;
            default: accept;
        }
    }

    state parse_ipv4 {
        packet.extract(hdr.ip4);
        transition select(hdr.ip4.protocol) {
            IP_PROTO_UDP: parse_udp;
            default: accept;
        }
    }

    state parse_udp {
        packet.extract(hdr.udp);
        transition accept;
    }
}


/*  Ingress Control  */
control MyIngress(inout headers_t hdr,
                  inout my_md_t   md,
                  inout standard_metadata_t sm) {


    action extract_input() {

        bit<8> p8 = (bit<8>) hdr.ip4.protocol[1:0];
        bit<8> d8 = (bit<8>) hdr.ip4.dscp[2:0];
        bit<8> u8 = (bit<8>) hdr.udp.dstPort[2:0];
        md.input_vector = (p8 << 6) | (d8 << 3) | u8;
    }


    action bnn_classify() {

        bit<8> w0; bnn_weights.read(w0, (bit<32>)0);
        bit<8> w1; bnn_weights.read(w1, (bit<32>)1);
        bit<8> w2; bnn_weights.read(w2, (bit<32>)2);
        bit<8> w3; bnn_weights.read(w3, (bit<32>)3);
        bit<8> w4; bnn_weights.read(w4, (bit<32>)4);
        bit<8> w5; bnn_weights.read(w5, (bit<32>)5);


/* XNOR + popcount */
        bit<4> s0 = popcnt8(~(w0 ^ md.input_vector));
        bit<4> s1 = popcnt8(~(w1 ^ md.input_vector));
        bit<4> s2 = popcnt8(~(w2 ^ md.input_vector));
        bit<4> s3 = popcnt8(~(w3 ^ md.input_vector));
        bit<4> s4 = popcnt8(~(w4 ^ md.input_vector));
        bit<4> s5 = popcnt8(~(w5 ^ md.input_vector));


        bit<3> best_class = 0;
        bit<4> best_score = s0;

        if (s1 > best_score) { best_score = s1; best_class = 1; }
        if (s2 > best_score) { best_score = s2; best_class = 2; }
        if (s3 > best_score) { best_score = s3; best_class = 3; }
        if (s4 > best_score) { best_score = s4; best_class = 4; }
        if (s5 > best_score) { best_score = s5; best_class = 5; }

        md.qos_class = best_class;
    }


    action set_dscp(bit<6> d)    { hdr.ip4.dscp = d; }
    action set_queue(bit<3> qid) { md.queue_id  = qid; }
    action set_out(bit<9> port)  { sm.egress_spec = port; }


    table dscp_mark {
        key = { md.qos_class: exact; }
        actions = { set_dscp; NoAction; }
        const entries = {
            (3w0): set_dscp(0);  (3w1): set_dscp(10);
            (3w2): set_dscp(18); (3w3): set_dscp(26);
            (3w4): set_dscp(34); (3w5): set_dscp(46);
        }
        default_action = NoAction();
    }

    table queue_map {
        key = { md.qos_class: exact; }
        actions = { set_queue; NoAction; }
        const entries = {
            (3w0): set_queue(0); (3w1): set_queue(1);
            (3w2): set_queue(2); (3w3): set_queue(3);
            (3w4): set_queue(4); (3w5): set_queue(5);
        }
        default_action = set_queue(0);
    }

    table l3_fwd {
        key = { hdr.ip4.dstAddr : lpm; }
        actions = { set_out; NoAction; }
        size = 1024;
        default_action = NoAction();
    }


    apply {
        if (hdr.ip4.isValid()) {
            hdr.ip4.ttl = hdr.ip4.ttl - 1;
        }

        extract_input();
        bnn_classify();


        dscp_mark.apply();
        queue_map.apply();
        l3_fwd.apply();

        if (sm.egress_spec == 0) {
            mark_to_drop(sm);
        }
    }
}


control MyEgress(inout headers_t hdr,
                 inout my_md_t   md,
                 inout standard_metadata_t sm) {
    apply {
        sm.egress_rid = (bit<16>) md.queue_id;
    }
}

control MyVerify(inout headers_t hdr, inout my_md_t md)  { apply { } }
control MyCompute(inout headers_t hdr, inout my_md_t md) { apply { } }


