const bit<16> ETH_TYPE_IPV4 = 0x0800;
const bit<16> ETH_TYPE_ARP  = 0x0806;
const bit<8>  IP_PROTO_TCP  = 6;
const bit<8>  IP_PROTO_UDP  = 17;
const bit<16> ARP_FLOOD_GID = 1;



typedef bit<48> mac_addr_t;
typedef bit<32> ipv4_addr_t;


header ethernet_t {
    mac_addr_t dst;
    mac_addr_t src;
    bit<16>    eth_type;
}
