}
header tcp_t {
    bit<16> srcPort;
    bit<16> dstPort;
    bit<32> seqNo;
    bit<32> ackNo;
    bit<4>  dataOffset;
    bit<3>  reserved;
    bit<9>  flags;
    bit<16> window;
    bit<16> checksum;
    bit<16> urgentPtr;
}


/*  Metadata  */
struct my_md_t {
    bit<3>  qos_class;
    bit<3>  queue_id;
    bit<16> l4_dport;
}


/*  Header container  */
struct headers_t {
    ethernet_t eth;
    arp_t      arp;
    ipv4_t     ip4;
    udp_t      udp;
    tcp_t      tcp;
}


/*  Parser  */
parser MyParser(packet_in pkt,
                out headers_t hdr,
                inout my_md_t md,
                inout standard_metadata_t sm) {
    state start {
        md.l4_dport  = 0;
        md.qos_class = 0;
        md.queue_id  = 0;
        transition parse_ethernet;
    }
    state parse_ethernet {
        pkt.extract(hdr.eth);
        transition select(hdr.eth.eth_type) {
            ETH_TYPE_ARP  : parse_arp;
            ETH_TYPE_IPV4 : parse_ipv4;
            default       : accept;
        }
    }
    state parse_arp {
        pkt.extract(hdr.arp);
        transition accept;
    }
    state parse_ipv4 {
        pkt.extract(hdr.ip4);
        transition select(hdr.ip4.protocol) {
            IP_PROTO_UDP: parse_udp;
            IP_PROTO_TCP: parse_tcp;
            default     : accept;
        }
    }
    state parse_udp {
        pkt.extract(hdr.udp);
        md.l4_dport = hdr.udp.dstPort;
        transition accept;
    }
    state parse_tcp {
        pkt.extract(hdr.tcp);
        md.l4_dport = hdr.tcp.dstPort;
        transition accept;
    }
}


/*  Verify checksum (placeholder)  */
control MyVerify(inout headers_t hdr, inout my_md_t md) {
    apply { }
}


/*  Ingress  */
control MyIngress(inout headers_t hdr,
                  inout my_md_t md,
                  inout standard_metadata_t sm) {

/* Actions */
    action set_qos(bit<3> cls)    { md.qos_class = cls; }
    action set_dscp(bit<6> d)     { hdr.ip4.dscp = d; }
    action set_queue(bit<3> q)    { md.queue_id = q; }
    action ipv4_forward(mac_addr_t mac, bit<9> port) {
        hdr.eth.dst    = mac;
        sm.egress_spec = port;
    }
    action drop()                 { mark_to_drop(sm); }


/* QoS tables */
    table qos_classify {
        key = {
            hdr.ip4.protocol : exact;
            md.l4_dport      : exact;
        }
        actions = { set_qos; }
        const entries = {
            (IP_PROTO_UDP, 4000): set_qos(0);
            (IP_PROTO_UDP, 4321): set_qos(5);
            (IP_PROTO_TCP, 80)  : set_qos(3);
            (IP_PROTO_UDP, 8080): set_qos(3);
        }
        default_action = set_qos(0);
    }

    table dscp_mark {
        key = { md.qos_class : exact; }
        actions = { set_dscp; NoAction; }
        const entries = {
            (3w0): set_dscp(0);
            (3w1): set_dscp(10);
            (3w2): set_dscp(18);
            (3w3): set_dscp(26);
            (3w4): set_dscp(34);
            (3w5): set_dscp(46);
        }
        default_action = NoAction();
    }

    table queue_map {
        key = { md.qos_class : exact; }
        actions = { set_queue; NoAction; }
        const entries = {
            (3w0): set_queue(0);
            (3w1): set_queue(1);
            (3w2): set_queue(2);
            (3w3): set_queue(3);
            (3w4): set_queue(4);
            (3w5): set_queue(5);
        }
        default_action = set_queue(0);
    }

    table ipv4_lpm {
        key = { hdr.ip4.dstAddr : lpm; }
        actions = { ipv4_forward; NoAction; }
        size = 1024;
        default_action = NoAction();
    }

    apply {
        if (hdr.eth.eth_type == ETH_TYPE_ARP && hdr.arp.isValid()) {
            sm.mcast_grp = ARP_FLOOD_GID;
            return;
        }
        if (hdr.ip4.isValid()) {
            if (hdr.ip4.ttl == 0) { drop(); return; }
            hdr.ip4.ttl = hdr.ip4.ttl - 1;
            if (hdr.ip4.ttl == 0) { drop(); return; }
        }
        qos_classify.apply();
        dscp_mark.apply();
        queue_map.apply();
        ipv4_lpm.apply();
        if (sm.egress_spec == 0) { drop(); }
    }
}


/*  Egress  */
control MyEgress(inout headers_t hdr,
                 inout my_md_t md,
                 inout standard_metadata_t sm) {
    apply {
        sm.priority = md.queue_id;
    }
}


/*  Checksum recompute  */
control MyCompute(inout headers_t hdr, inout my_md_t md) {
    apply {
        update_checksum(
            hdr.ip4.isValid(),
            { hdr.ip4.version, hdr.ip4.ihl, hdr.ip4.dscp, hdr.ip4.ecn,
              hdr.ip4.totalLen, hdr.ip4.identification, hdr.ip4.flags,
              hdr.ip4.fragOffset, hdr.ip4.ttl, hdr.ip4.protocol,
              hdr.ip4.srcAddr, hdr.ip4.dstAddr },
            hdr.ip4.hdrChecksum,
            HashAlgorithm.csum16
        );
    }
}


/*  Deparser  */
control MyDeparser(packet_out pkt, in headers_t hdr) {
    apply {
        pkt.emit(hdr.eth);
        pkt.emit(hdr.arp);
        pkt.emit(hdr.ip4);
        pkt.emit(hdr.udp);
        pkt.emit(hdr.tcp);
    }
}


/*  Switch instance  */
V1Switch(
    MyParser(),
    MyVerify(),
    MyIngress(),
    MyEgress(),
    MyCompute(),
    MyDeparser()
) main;

#include <core.p4>

#include <v1model.p4>

const bit<16> TYPE_IPV4 = 0x800;





typedef bit<9>  egressSpec_t;

typedef bit<48> macAddr_t;

typedef bit<32> ip4Addr_t;



register<bit<10>>(1024) syn_cnt;

register<bit<10>>(1024) syn_ack_cnt;



header ethernet_t {

    macAddr_t dstAddr;

    macAddr_t srcAddr;

    bit<16>   etherType;

}



header ipv4_t {

    bit<4>    version;

    bit<4>    ihl;

    bit<8>    diffserv;

    bit<16>   totalLen;

    bit<16>   identification;

    bit<3>    flags;

    bit<13>   fragOffset;

    bit<8>    ttl;

    bit<8>    protocol;

    bit<16>   hdrChecksum;

    ip4Addr_t srcAddr;

    ip4Addr_t dstAddr;

}



header tcp_t {

    bit<16> srcPort;

    bit<16> dstPort;

    bit<32> seqNo;

    bit<32> ackNo;

    bit<4>  dataOffset;

    bit<4>  res;

    bit<8>  flags;

    bit<16> window;

    bit<16> checksum;

    bit<16> urgentPtr;

}



header udp_t {

    bit<16> srcPort;

    bit<16> dstPort;

    bit<16> udplength;

    bit<16> checksum;

}



struct metadata {

    bit<10>   flowlet_map_index;

    bit<10>    syn_count;

    bit<10>    syn_ack_count;

}



struct headers {

    ethernet_t   ethernet;

    ipv4_t       ipv4;

    tcp_t        tcp;

    udp_t       udp;

}





parser MyParser(packet_in packet,

                out headers hdr,

                inout metadata meta,

                inout standard_metadata_t standard_metadata) {



    state start {

        transition parse_ethernet;

    }



    state parse_ethernet {

        packet.extract(hdr.ethernet);

        transition select(hdr.ethernet.etherType) {

            TYPE_IPV4: parse_ipv4;

            default: accept;

        }

    }



    state parse_ipv4 {

        packet.extract(hdr.ipv4);

        transition select(hdr.ipv4.protocol) {

            0x06: parse_tcp;

            0x11: parse_udp;

            default: accept;

        }

    }



    state parse_tcp {

        packet.extract(hdr.tcp);

        transition accept; 

    }



    state parse_udp {

        packet.extract(hdr.udp);

        transition accept; 

    }

}





control MyVerifyChecksum(inout headers hdr, inout metadata meta) { 

    apply {  }

}





control MyIngress(inout headers hdr,

                  inout metadata meta,

                  inout standard_metadata_t standard_metadata) {



    action add_syn_cnt() {

        hash(meta.flowlet_map_index, HashAlgorithm.crc16, (bit<16>)0, { hdr.ipv4.srcAddr }, (bit<32>)1024);

        syn_cnt.read(meta.syn_count, (bit<32>)meta.flowlet_map_index);

        meta.syn_count=meta.syn_count+1;

        syn_cnt.write((bit<32>)meta.flowlet_map_index, meta.syn_count);

    }



    action add_syn_ack_cnt() {

        hash(meta.flowlet_map_index, HashAlgorithm.crc16, (bit<16>)0, { hdr.ipv4.dstAddr }, (bit<32>)1024);

        syn_ack_cnt.read(meta.syn_ack_count, (bit<32>)meta.flowlet_map_index);

        meta.syn_ack_count=meta.syn_ack_count+1;

        syn_ack_cnt.write((bit<32>)meta.flowlet_map_index, meta.syn_ack_count);

    } 



    action drop() {

        mark_to_drop(standard_metadata);

    }



    action forward(macAddr_t dstAddr, egressSpec_t port) {

        hdr.ethernet.srcAddr = hdr.ethernet.dstAddr;

        hdr.ethernet.dstAddr = dstAddr;

        standard_metadata.egress_spec = port;

        hdr.ipv4.ttl = hdr.ipv4.ttl - 1;

    }



    table ip_forward {

        key = {

            hdr.ipv4.dstAddr: lpm;

        }

        actions = {

            forward;

            drop;

        }

        size = 1024;

        default_action = drop();

    }



    apply {

        bit<1> set_drop=0;

        if (hdr.tcp.isValid()){

           if(hdr.tcp.flags==2) {

             add_syn_cnt();



             hash(meta.flowlet_map_index, HashAlgorithm.crc16, (bit<16>)0, { hdr.ipv4.srcAddr }, (bit<32>)1024);

             bit<10> tmp;

             syn_ack_cnt.read(tmp, (bit<32>)meta.flowlet_map_index);

             if(tmp==0 && meta.syn_count>3){

               set_drop=1;

             }

             if (tmp!=0 && meta.syn_count > (bit<10>)(3+tmp)){

               set_drop=1; 

             }

           } else if (hdr.tcp.flags==0x12) {

             add_syn_ack_cnt();

           }

        }



        if( hdr.ipv4.isValid() && set_drop==0){

             ip_forward.apply();

        }

    }

}





control MyEgress(inout headers hdr,

                 inout metadata meta,

                 inout standard_metadata_t standard_metadata) {

    apply {  }

}





control MyComputeChecksum(inout headers  hdr, inout metadata meta) {

     apply {

        update_checksum(

            hdr.ipv4.isValid(),

            { hdr.ipv4.version,

              hdr.ipv4.ihl,

              hdr.ipv4.diffserv,

              hdr.ipv4.totalLen,

              hdr.ipv4.identification,

              hdr.ipv4.flags,

              hdr.ipv4.fragOffset,

              hdr.ipv4.ttl,

              hdr.ipv4.protocol,

              hdr.ipv4.srcAddr,

              hdr.ipv4.dstAddr },

            hdr.ipv4.hdrChecksum,

            HashAlgorithm.csum16);

    }

}





control MyDeparser(packet_out packet, in headers hdr) {

    apply {

        packet.emit(hdr.ethernet);

        packet.emit(hdr.ipv4);

        packet.emit(hdr.tcp);

        packet.emit(hdr.udp);

    }

}





V1Switch(

MyParser(),

MyVerifyChecksum(),

MyIngress(),

MyEgress(),

MyComputeChecksum(),

MyDeparser()

) main;

#include <core.p4>
#include <v1model.p4>


typedef bit<9>  egressSpec_t;
typedef bit<48> macAddr_t;
typedef bit<32> ip4Addr_t;


// Change these values according to the value reprentations of the problem domain.
typedef bit<8>  sensor_id_t;
typedef bit<8>  sensor_value_t;


// Simple state machine representing the result of matching rules.
enum bit<8> rule_match_kind {
  no_match_initiated = 0,

// no rule lookup happened
  no_rule_found      = 1,

// lookup happened but no rule defined for the given sensor id
  evaluated_to_true  = 2,

// lookup happened and the corresponding rule evaluated to true
  evaluated_to_false = 3

// same as above but evaluated to false
}


// It carries information from MyIngress to MyEgress
struct metadata {
  rule_match_kind match;
}

enum bit<16> ethernet_kind {
  ipv4   = 0x800,
  sensor = 0x842

// dummy ethernet type representing the sensor packets
}

header ethernet_t {
  macAddr_t dstAddr;
  macAddr_t srcAddr;
  ethernet_kind etherType;
}

header ipv4_t {
  bit<4>  version;
  bit<4>  ihl;
  bit<8>  diffserv;
  bit<16> totalLen;
  bit<16> identification;
  bit<3>  flags;
  bit<13> fragOffset;
  bit<8>  ttl;
  bit<8>  protocol;
  bit<16> hdrChecksum;
  ip4Addr_t srcAddr;
  ip4Addr_t dstAddr;
}


// Represents a sensor measurement.
header sensor_data {
  sensor_id_t sensor_id;

// the identifier of the producer sensor (it is used by the id## fields of a rule)
  sensor_value_t sensor_value;
}


header rule_match_result {
  rule_match_kind match;
}

struct headers {
  ethernet_t ethernet;
  ipv4_t ipv4;
  sensor_data sensordata;
  rule_match_result result;
}


enum bit<3> op_t {
  invalid = 0,
  lt      = 1,
  le      = 2,
  gt      = 3,
  ge      = 4,
  eq      = 5,
  ne      = 6
}

const bit<32> maximum_number_of_sensors = 7;
const bit<32> maximum_number_of_rules = 10;
const bit<32> number_of_ors = 3;
const bit<32> number_of_ands = 4;




struct rule_t {

// note: unfortunately nested structs are not yet implemented by the p4 compiler, so unrolled this by hand
  sensor_id_t    id00;
  op_t           op00;
  sensor_value_t constant00;

  sensor_id_t    id01;
  op_t           op01;
  sensor_value_t constant01;

  sensor_id_t    id02;
  op_t           op02;
  sensor_value_t constant02;

  sensor_id_t    id03;
  op_t           op03;
  sensor_value_t constant03;

  sensor_id_t    id10;
  op_t           op10;
  sensor_value_t constant10;

  sensor_id_t    id11;
  op_t           op11;
  sensor_value_t constant11;

  sensor_id_t    id12;
  op_t           op12;
  sensor_value_t constant12;

  sensor_id_t    id13;
  op_t           op13;
  sensor_value_t constant13;

  sensor_id_t    id20;
  op_t           op20;
  sensor_value_t constant20;

  sensor_id_t    id21;
  op_t           op21;
  sensor_value_t constant21;

  sensor_id_t    id22;
  op_t           op22;
  sensor_value_t constant22;

  sensor_id_t    id23;
  op_t           op23;
  sensor_value_t constant23;
}

parser MyParser(packet_in packet, out headers hdr, inout metadata meta, inout standard_metadata_t standard_metadata) {
  state parse_ethernet {
    packet.extract(hdr.ethernet);
    transition select(hdr.ethernet.etherType) {
      ethernet_kind.ipv4:   parse_ipv4;
      ethernet_kind.sensor: parse_sensor_data;
      default: accept;
    }
  }

  state parse_ipv4 {
    packet.extract(hdr.ipv4);
    transition accept;
  }
  state parse_sensor_data {
    packet.extract(hdr.sensordata);
    transition parse_ipv4;
  }

  state start {
    transition parse_ethernet;
  }
}

control MyVerifyChecksum(inout headers hdr, inout metadata meta) {
  apply { }
}

bool isOpValid(in op_t op) {
  return op != op_t.invalid;
}


bool eval_triplet(in sensor_value_t val, in op_t op, in sensor_value_t constant) {

// assuming valid op
  if (op == op_t.lt)
    return val < constant;
  if (op == op_t.le)
    return val <= constant;
  if (op == op_t.gt)
    return val > constant;
  if (op == op_t.ge)
    return val >= constant;
  if (op == op_t.eq)
    return val == constant;

  return val != constant;
}


control MyIngress(inout headers hdr, inout metadata meta, inout standard_metadata_t standard_metadata) {

  register<sensor_value_t>(maximum_number_of_sensors) sensor_history;

  action drop() {
    mark_to_drop(standard_metadata);
  }

  action default_handler() {
    meta.match = rule_match_kind.no_rule_found;
  }


  action apply_rule(
    sensor_id_t id00, op_t op00, sensor_value_t constant00,
    sensor_id_t id01, op_t op01, sensor_value_t constant01,
    sensor_id_t id02, op_t op02, sensor_value_t constant02,
    sensor_id_t id03, op_t op03, sensor_value_t constant03,
    sensor_id_t id10, op_t op10, sensor_value_t constant10,
    sensor_id_t id11, op_t op11, sensor_value_t constant11,
    sensor_id_t id12, op_t op12, sensor_value_t constant12,
    sensor_id_t id13, op_t op13, sensor_value_t constant13,
    sensor_id_t id20, op_t op20, sensor_value_t constant20,
    sensor_id_t id21, op_t op21, sensor_value_t constant21,
    sensor_id_t id22, op_t op22, sensor_value_t constant22,
    sensor_id_t id23, op_t op23, sensor_value_t constant23) {


// save current sensor value
    sensor_history.write((bit<32>)hdr.sensordata.sensor_id, hdr.sensordata.sensor_value);

    sensor_value_t value00;
    sensor_value_t value01;
    sensor_value_t value02;
    sensor_value_t value03;
    sensor_value_t value10;
    sensor_value_t value11;
    sensor_value_t value12;
    sensor_value_t value13;
    sensor_value_t value20;
    sensor_value_t value21;
    sensor_value_t value22;
    sensor_value_t value23;


    sensor_history.read(value00, (bit<32>)id00);
    sensor_history.read(value01, (bit<32>)id01);
    sensor_history.read(value02, (bit<32>)id02);
    sensor_history.read(value03, (bit<32>)id03);
    sensor_history.read(value10, (bit<32>)id10);
    sensor_history.read(value11, (bit<32>)id11);
    sensor_history.read(value12, (bit<32>)id12);
    sensor_history.read(value13, (bit<32>)id13);
    sensor_history.read(value20, (bit<32>)id20);
    sensor_history.read(value21, (bit<32>)id21);
    sensor_history.read(value22, (bit<32>)id22);
    sensor_history.read(value23, (bit<32>)id23);



    bool group0 = (!isOpValid(op00) || eval_triplet(value00, op00, constant00)) &&
                  (!isOpValid(op01) || eval_triplet(value01, op01, constant01)) &&
                  (!isOpValid(op02) || eval_triplet(value02, op02, constant02)) &&
                  (!isOpValid(op03) || eval_triplet(value03, op03, constant03));
    bool group1 = (!isOpValid(op10) || eval_triplet(value10, op10, constant10)) &&
                  (!isOpValid(op11) || eval_triplet(value11, op11, constant11)) &&
                  (!isOpValid(op12) || eval_triplet(value12, op12, constant12)) &&
                  (!isOpValid(op13) || eval_triplet(value13, op13, constant13));
    bool group2 = (!isOpValid(op20) || eval_triplet(value20, op20, constant20)) &&
                  (!isOpValid(op21) || eval_triplet(value21, op21, constant21)) &&
                  (!isOpValid(op22) || eval_triplet(value22, op22, constant22)) &&
                  (!isOpValid(op23) || eval_triplet(value23, op23, constant23));

    meta.match = (group0 || group1 || group2) ? rule_match_kind.evaluated_to_true
                                              : rule_match_kind.evaluated_to_false;
  }

  table sensor_to_rule_mapping {
    actions = {
      default_handler;
      apply_rule;
    }
    key = {
      hdr.sensordata.sensor_id: exact;
    }
    size = maximum_number_of_rules;
    default_action = default_handler();
  }


  action ipv4_forward(macAddr_t dstAddr, egressSpec_t port) {
    standard_metadata.egress_spec = port;
    hdr.ethernet.srcAddr = hdr.ethernet.dstAddr;
    hdr.ethernet.dstAddr = dstAddr;
    hdr.ipv4.ttl = hdr.ipv4.ttl - 1;
  }
  table ipv4_lpm {
    key = {
      hdr.ipv4.dstAddr: lpm;
    }
    actions = {
      ipv4_forward;
      drop;
      NoAction;
    }
    size = 1024;
    default_action = drop();
  }

  apply {
    meta.match = rule_match_kind.no_match_initiated;
    if (hdr.sensordata.isValid())
      sensor_to_rule_mapping.apply();
    if (hdr.ipv4.isValid())
      ipv4_lpm.apply();
  }
}

control MyEgress(inout headers hdr, inout metadata meta, inout standard_metadata_t standard_metadata) {
  apply {
    if (meta.match != rule_match_kind.no_match_initiated) {
      hdr.result.setValid();
      hdr.result.match = meta.match;
    }
  }
}

control MyComputeChecksum(inout headers hdr, inout metadata meta) {
  apply {
    update_checksum(
      hdr.ipv4.isValid(),
      {
        hdr.ipv4.version,
        hdr.ipv4.ihl,
        hdr.ipv4.diffserv,
        hdr.ipv4.totalLen,
        hdr.ipv4.identification,
        hdr.ipv4.flags,
        hdr.ipv4.fragOffset,
        hdr.ipv4.ttl,
        hdr.ipv4.protocol,
        hdr.ipv4.srcAddr,
        hdr.ipv4.dstAddr
      },
      hdr.ipv4.hdrChecksum,
      HashAlgorithm.csum16);
  }
}

control MyDeparser(packet_out packet, in headers hdr) {
  apply {

// note: we no longer emit the sensordata, only the match result
    packet.emit(hdr.ethernet);
    packet.emit(hdr.ipv4);
    packet.emit(hdr.result);
  }
}

V1Switch(MyParser(), MyVerifyChecksum(), MyIngress(), MyEgress(), MyComputeChecksum(), MyDeparser()) main;

#include <core.p4>
#include <v1model.p4>

#define DDPV_DATA_LEN 12
#define DDPV_REPORT_LEN 10
#define DDPV_DATA_LEN_4B 3
#define BLOOM_LEN 96

const bit<16> TYPE_IPV4 = 0x800;
const bit<8> TYPE_TCP = 0x6;
const bit<8> TYPE_UDP = 0x11;
const bit<32> SKETCH_LEN = 100000;
const bit<7> BLOOM_INDEX_LEN = BLOOM_LEN;
const bit<9> DROP_PORT = 511;



typedef bit<9>  egressSpec_t;
typedef bit<48> macAddr_t;
typedef bit<32> ip4Addr_t;
typedef bit<9> port_t;
typedef bit<6> suffix_t;

header ethernet_t {
    macAddr_t dstAddr;
    macAddr_t srcAddr;
    bit<16>   etherType;
}

header ipv4_t {
    bit<4>    version;
    bit<4>    ihl;
    bit<8>    diffserv;
    bit<16>   totalLen;
    bit<16>   identification;
    bit<3>    flags;
    bit<13>   fragOffset;
    bit<8>    ttl;
    bit<8>    protocol;
    bit<16>   hdrChecksum;
    ip4Addr_t srcAddr;
    ip4Addr_t dstAddr;
}


header ddpv_data_t {
    bit<BLOOM_LEN>  bloom_filter;
}

header ddpv_report_t {
    macAddr_t device_id;
    ip4Addr_t ip_dst;
}

header tcp_t {
    bit<16> srcPort;
    bit<16> dstPort;
    bit<32> seqNo;
    bit<32> ackNo;
    bit<4>  dataOffset;
    bit<3>  res;
    bit<3>  ecn;
    bit<6>  ctrl;
    bit<16> window;
    bit<16> checksum;
    bit<16> urgentPtr;
}

header udp_t {
    bit<16> srcPort;
    bit<16> dstPort;
    bit<16> len;
    bit<16> checksum;
}



struct metadata {
    bit<32>      mec_index1;
    bit<32>      mec_index2;
    bit<32>      mec_index3;
    bit<32>      sp_index1;
    bit<32>      sp_index2;
    bit<32>      sp_index3;

    bit<7>       bloom_index1;
    bit<7>       bloom_index2;
    bit<7>       bloom_index3;
    bit<7>       bloom_index4;

    bit<BLOOM_LEN>       bloom_value1;
    bit<BLOOM_LEN>       bloom_value2;
    bit<BLOOM_LEN>       bloom_value3;
    bit<BLOOM_LEN>       bloom_value4;

    suffix_t       suffix;

}

struct headers {
    ethernet_t    ethernet;
    ipv4_t        ipv4;  
    ddpv_data_t   ddpv_data;
    ddpv_report_t ddpv_report;
    tcp_t         tcp;
    udp_t         udp;
}



parser MyParser(packet_in packet,
                out headers hdr,
                inout metadata meta,
                inout standard_metadata_t standard_metadata) {

    state start {
        transition parse_ethernet;
    }

    state parse_ethernet {
        packet.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType) {
            TYPE_IPV4: parse_ipv4;
            default: accept;
        }
    }

    state parse_ipv4 {
        packet.extract(hdr.ipv4);
        transition select(hdr.ipv4.ihl){
            5: parse_l4_proto;
            8: parse_ddpv_data;
        }
    }

    state parse_l4_proto{
        transition select(hdr.ipv4.protocol) {
            TYPE_TCP: parse_tcp;
            TYPE_UDP: parse_udp;
            default:  accept;
        }
    }

    state parse_ddpv_data {
        packet.extract(hdr.ddpv_data);
        transition parse_l4_proto;
    }

    state parse_tcp {
        packet.extract(hdr.tcp);
        transition accept;
    }

    state parse_udp {
        packet.extract(hdr.udp);
        transition accept;
    }
}




control MyVerifyChecksum(inout headers hdr, inout metadata meta) {
    apply {  }
}




control MyIngress(inout headers hdr,
                  inout metadata meta,
                  inout standard_metadata_t standard_metadata) {
    register<port_t>(SKETCH_LEN) mec_port_reg1;
    register<port_t>(SKETCH_LEN) mec_port_reg2;
    register<port_t>(SKETCH_LEN) mec_port_reg3;

    register<port_t>(SKETCH_LEN) sp_port_reg1;
    register<port_t>(SKETCH_LEN) sp_port_reg2;
    register<port_t>(SKETCH_LEN) sp_port_reg3;

    action drop() {
        mark_to_drop(standard_metadata);
    }

    action ipv4_forward(macAddr_t dstAddr, egressSpec_t port, suffix_t suffix) {
        standard_metadata.egress_spec = port;
        hdr.ethernet.srcAddr = hdr.ethernet.dstAddr;
        hdr.ethernet.dstAddr = dstAddr;
        hdr.ipv4.ttl = hdr.ipv4.ttl - 1;

        meta.suffix = suffix;
    }

    action calculate_sketch_index() {
        hash(meta.sp_index1,HashAlgorithm.crc32_custom,32w0,{hdr.ipv4.dstAddr},SKETCH_LEN);
        hash(meta.sp_index2,HashAlgorithm.crc32_custom,32w0,{hdr.ipv4.dstAddr},SKETCH_LEN);
        hash(meta.sp_index3,HashAlgorithm.crc32_custom,32w0,{hdr.ipv4.dstAddr},SKETCH_LEN);
        bit<32> mec_id = hdr.ipv4.dstAddr & 0xffffff00;
        hash(meta.mec_index1,HashAlgorithm.crc32_custom,32w0,{mec_id},SKETCH_LEN);
        hash(meta.mec_index2,HashAlgorithm.crc32_custom,32w0,{mec_id},SKETCH_LEN);
        hash(meta.mec_index3,HashAlgorithm.crc32_custom,32w0,{mec_id},SKETCH_LEN);
    }

    action calculate_bloom_filter_index() {
        hash(meta.bloom_index1,HashAlgorithm.crc32_custom,32w0,{hdr.ethernet.srcAddr},BLOOM_INDEX_LEN);
        hash(meta.bloom_index2,HashAlgorithm.crc32_custom,32w0,{hdr.ethernet.srcAddr},BLOOM_INDEX_LEN);
        hash(meta.bloom_index3,HashAlgorithm.crc32_custom,32w0,{hdr.ethernet.srcAddr},BLOOM_INDEX_LEN);
        hash(meta.bloom_index4,HashAlgorithm.crc32_custom,32w0,{hdr.ethernet.srcAddr},BLOOM_INDEX_LEN);
        meta.bloom_value1=(bit<BLOOM_LEN>)1<<meta.bloom_index1;
        meta.bloom_value2=(bit<BLOOM_LEN>)1<<meta.bloom_index2;
        meta.bloom_value3=(bit<BLOOM_LEN>)1<<meta.bloom_index3;
        meta.bloom_value4=(bit<BLOOM_LEN>)1<<meta.bloom_index4;
    }

    table ipv4_lpm {
        key = {
            hdr.ipv4.dstAddr: lpm;
        }
        actions = {
            ipv4_forward;
            drop;
        }
        default_action = drop();
    }

    apply {
        port_t sp_v1;
        port_t sp_v2;
        port_t sp_v3;
        port_t sp_v;

        port_t mec_v1;
        port_t mec_v2;
        port_t mec_v3;
        port_t mec_v;

        if(hdr.ipv4.isValid()){
            if(hdr.ipv4.ttl==0) mark_to_drop(standard_metadata);
            else{
                ipv4_lpm.apply();
            }
            if(standard_metadata.egress_spec!=DROP_PORT&&!hdr.ddpv_report.isValid()&&(hdr.ipv4.protocol==TYPE_TCP || hdr.ipv4.protocol==TYPE_UDP)){
                bit<1> modification_marker=0;
                calculate_bloom_filter_index();
                bit<3> count=0;
                if(hdr.ddpv_data.isValid()){
                    if(meta.bloom_value1&hdr.ddpv_data.bloom_filter==meta.bloom_value1) count=count+1;
                    if(meta.bloom_value2&hdr.ddpv_data.bloom_filter==meta.bloom_value2) count=count+1;
                    if(meta.bloom_value3&hdr.ddpv_data.bloom_filter==meta.bloom_value3) count=count+1;
                    if(meta.bloom_value4&hdr.ddpv_data.bloom_filter==meta.bloom_value4) count=count+1;
                }

                if(count==4){
                    hdr.ddpv_data.setInvalid();
                    hdr.ethernet.dstAddr = 0xffffffffff17;
                    hdr.ipv4.ihl=5;
                    hdr.ipv4.protocol = 147;
                    hdr.ipv4.totalLen=34 + DDPV_REPORT_LEN;
                    hdr.ddpv_report.setValid();
                    hdr.ddpv_report.device_id = hdr.ethernet.srcAddr;
                    hdr.ddpv_report.ip_dst = hdr.ipv4.dstAddr;
                    hdr.ipv4.dstAddr = 0xffffff11;
                    truncate(34 + DDPV_REPORT_LEN);
                    standard_metadata.egress_spec = (port_t)42;
                }else{
                    calculate_sketch_index();

                    mec_port_reg1.read(mec_v1,(bit<32>)meta.mec_index1);
                    mec_port_reg2.read(mec_v2,(bit<32>)meta.mec_index2);
                    mec_port_reg3.read(mec_v3,(bit<32>)meta.mec_index3);
                    sp_port_reg1.read(sp_v1,(bit<32>)meta.sp_index1);
                    sp_port_reg2.read(sp_v2,(bit<32>)meta.sp_index2);
                    sp_port_reg3.read(sp_v3,(bit<32>)meta.sp_index3);

                    if(mec_v1==mec_v2&&mec_v2==mec_v3||mec_v1==mec_v2){
                        mec_v=mec_v1;
                    }else if(mec_v3==mec_v1||mec_v3==mec_v2){
                        mec_v=mec_v3;
                    }else {
                        mec_v=0;
                    }

                    if(sp_v1==sp_v2&&sp_v2==sp_v3||sp_v1==sp_v2){
                        sp_v=sp_v1;
                    }else if(sp_v3==sp_v1||sp_v3==sp_v2){
                        sp_v=sp_v3;
                    }else {
                        sp_v=0;
                    }

                    if(meta.suffix <=24){
                        mec_port_reg1.write((bit<32>)meta.mec_index1,standard_metadata.egress_spec);
                        mec_port_reg2.write((bit<32>)meta.mec_index2,standard_metadata.egress_spec);
                        mec_port_reg3.write((bit<32>)meta.mec_index3,standard_metadata.egress_spec);
                        if(sp_v!=0){
                            if(sp_v1==sp_v) sp_port_reg1.write((bit<32>)meta.sp_index1,standard_metadata.egress_spec);
                            if(sp_v2==sp_v) sp_port_reg2.write((bit<32>)meta.sp_index2,standard_metadata.egress_spec);
                            if(sp_v3==sp_v) sp_port_reg3.write((bit<32>)meta.sp_index3,standard_metadata.egress_spec);
                         if(sp_v!=standard_metadata.egress_spec) modification_marker=1;
                        }else{
                            if(mec_v!=standard_metadata.egress_spec) modification_marker=1;
                        }
                    }else{
                        sp_port_reg1.write((bit<32>)meta.sp_index1,standard_metadata.egress_spec);
                        sp_port_reg2.write((bit<32>)meta.sp_index2,standard_metadata.egress_spec);
                        sp_port_reg3.write((bit<32>)meta.sp_index3,standard_metadata.egress_spec);
                        if(sp_v!=standard_metadata.egress_spec)
                            modification_marker=1;
                        } 

                    if(modification_marker==1){
                       if(!hdr.ddpv_data.isValid()){
                            hdr.ddpv_data.setValid();
                            hdr.ddpv_data.bloom_filter=0;
                            hdr.ipv4.ihl=hdr.ipv4.ihl+DDPV_DATA_LEN_4B;
                            hdr.ipv4.totalLen=hdr.ipv4.totalLen+DDPV_DATA_LEN;
                        }
                        hdr.ddpv_data.bloom_filter = hdr.ddpv_data.bloom_filter | meta.bloom_value1;
                        hdr.ddpv_data.bloom_filter = hdr.ddpv_data.bloom_filter | meta.bloom_value2;
                        hdr.ddpv_data.bloom_filter = hdr.ddpv_data.bloom_filter | meta.bloom_value3;
                        hdr.ddpv_data.bloom_filter = hdr.ddpv_data.bloom_filter | meta.bloom_value4;
                    }
                }
            }     
        }
    }
}



