const bit<16> TYPE_IPV4 = 0x800;



const bit<8> TYPE_TCP = 6;
const bit<8> TYPE_UDP = 17;

typedef bit<9>  egressSpec_t;
typedef bit<48> macAddr_t;
typedef bit<32> ip4Addr_t;

header cpu_header_t {
    bit<8>    flag;
}

header ethernet_t {
    macAddr_t dstAddr;
    macAddr_t srcAddr;
    bit<16>   etherType;
}

header ipv4_t {
    bit<4>    version;
    bit<4>    ihl;
    bit<8>    diffserv;
    bit<16>   totalLen;
    bit<16>   identification;
    bit<3>    flags;
    bit<13>   fragOffset;
    bit<8>    ttl;
    bit<8>    protocol;
    bit<16>   hdrChecksum;
    ip4Addr_t srcAddr;
    ip4Addr_t dstAddr;
}

header tcp_t {
    bit<16> srcPort;
    bit<16> dstPort;
    bit<32> seqNo;
    bit<32> ackNo;
    bit<4>  dataOffset;
    bit<4>  res;
    bit<8>  flags;
    bit<16> window;
    bit<16> checksum;
    bit<16> urgentPtr;
}

header udp_t {
    bit<16> srcPort;
    bit<16> dstPort;
    bit<16> udplen;
    bit<16> udpchk;
}

struct custom_metadata_t {
    bit<32> hash_val1;
    bit<32> hash_val2;
    bit<32> hash_val3;
    bit<32> hash_val4;
    bit<32> hash_val5;
    bit<32> hash_val6;
    bit<32> hash_val7;
    bit<32> hash_val8;
    bit<32> hash_val9;
    bit<32> hash_val10;

    bit<32> count_val1;
    bit<32> count_val2;
    bit<32> count_val3;
    bit<32> count_val4;
    bit<32> count_val5;
    bit<32> count_val6;
    bit<32> count_val7;
    bit<32> count_val8;
    bit<32> count_val9;
    bit<32> count_val10;

    bit<32> count_min;
    bit<32> count_tot;
    bit<32> sum;
}

enum bit<8> FieldLists {
    none = 0,
    redirect_FL = 1
}

struct metadata {
    @field_list(FieldLists.redirect_FL)
    custom_metadata_t custom_metadata;
    bit<32> current_queue_bound;
    bit<32> queue_past_count;
    bit<16>  tcpLength;
}

struct headers {
    cpu_header_t cpu_header;
    ethernet_t   ethernet;
    ipv4_t       ipv4;
    tcp_t        tcp;
    udp_t        udp;
}



parser MyParser(packet_in packet,
                out headers hdr,
                inout metadata meta,
                inout standard_metadata_t standard_metadata) {

    state start {

        packet.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType){

            TYPE_IPV4: ipv4;
            default: accept;
        }
    }

    state ipv4 {
        packet.extract(hdr.ipv4);

        transition select(hdr.ipv4.protocol){
            TYPE_UDP: udp;
            TYPE_TCP: tcp;
            default: accept;
        }
    }

    state tcp {
       packet.extract(hdr.tcp);
       transition accept;
    }

    state udp {
       packet.extract(hdr.udp);
       transition accept;
    }

}

