#include <core.p4>
#include <v1model.p4>

const bit<16> TYPE_IPV4 = 0x800;



const bit<8> TYPE_TCP = 6;
const bit<8> TYPE_UDP = 17;

typedef bit<9>  egressSpec_t;
typedef bit<48> macAddr_t;
typedef bit<32> ip4Addr_t;

header cpu_header_t {
    bit<8>    flag;
}

header ethernet_t {
    macAddr_t dstAddr;
    macAddr_t srcAddr;
    bit<16>   etherType;
}

header ipv4_t {
    bit<4>    version;
    bit<4>    ihl;
    bit<8>    diffserv;
    bit<16>   totalLen;
    bit<16>   identification;
    bit<3>    flags;
    bit<13>   fragOffset;
    bit<8>    ttl;
    bit<8>    protocol;
    bit<16>   hdrChecksum;
    ip4Addr_t srcAddr;
    ip4Addr_t dstAddr;
}

header tcp_t {
    bit<16> srcPort;
    bit<16> dstPort;
    bit<32> seqNo;
    bit<32> ackNo;
    bit<4>  dataOffset;
    bit<4>  res;
    bit<1>  cwr;
    bit<1>  ece;
    bit<1>  urg;
    bit<1>  ack;
    bit<1>  psh;
    bit<1>  rst;
    bit<1>  syn;
    bit<1>  fin;
    bit<16> window;
    bit<16> checksum;
    bit<16> urgentPtr;
}

header udp_t {
    bit<16> srcPort;
    bit<16> dstPort;
    bit<16> udplen;
    bit<16> udpchk;
}

struct custom_metadata_t {
    bit<32> hash_val1;
    bit<32> hash_val2;
    bit<32> hash_val3;
    bit<32> hash_val4;
    bit<32> hash_val5;
    bit<32> hash_val6;
    bit<32> hash_val7;
    bit<32> hash_val8;
    bit<32> hash_val9;
    bit<32> hash_val10;

    bit<32> count_val1;
    bit<32> count_val2;
    bit<32> count_val3;
    bit<32> count_val4;
    bit<32> count_val5;
    bit<32> count_val6;
    bit<32> count_val7;
    bit<32> count_val8;
    bit<32> count_val9;
    bit<32> count_val10;

    bit<32> count_min;
    bit<32> count_tot;
    bit<32> sample_threshold;
    bit<16> index;
    bit<32> hh_threshold;
    bit<32> count_max;
    bit<32> count_max_final;
    bit<32> sample_hash_value;
    bit<32> current_count;
    bit<32> sum;
}

struct heavy_hitter_t {
    bit<32> srcAddr;
    bit<32> dstAddr;
    bit<32> count;
}

enum bit<8> FieldLists {
    none = 0,
    redirect_FL = 1
}

struct metadata {
    @field_list(FieldLists.redirect_FL)
    custom_metadata_t custom_metadata;
    heavy_hitter_t heavy_hitter;
}

struct headers {
    cpu_header_t cpu_header;
    ethernet_t   ethernet;
    ipv4_t       ipv4;
    tcp_t        tcp;
    udp_t        udp;
}



parser MyParser(packet_in packet,
                out headers hdr,
                inout metadata meta,
                inout standard_metadata_t standard_metadata) {

    state start {

        packet.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType){

            TYPE_IPV4: ipv4;
            default: accept;
        }
    }

    state ipv4 {
        packet.extract(hdr.ipv4);

        transition select(hdr.ipv4.protocol){
            TYPE_UDP: udp;
            TYPE_TCP: tcp;
            default: accept;
        }
    }

    state tcp {
       packet.extract(hdr.tcp);
       transition accept;
    }

    state udp {
       packet.extract(hdr.udp);
       transition accept;
    }

}

#define CPU_MIRROR_SESSION_ID 250
#define MIN 1
#define SKETCH_CELL_BIT_WIDTH 32
#define CM_ROW 30
#define THETA 5
#define EPSILON_INVERSE 10000
#define K 10
#define W 3
#define SAMPLELIST_SIZE 30
#define MAXIMUM_PACKETS 10

#define SKETCH_REGISTER(num) register<bit<SKETCH_CELL_BIT_WIDTH>>(CM_ROW) sketch##num
#define SKETCH_COUNT(num, algorithm) hash(meta.custom_metadata.hash_val##num, HashAlgorithm.algorithm, (bit<16>)0, {hdr.ipv4.srcAddr, \
 hdr.ipv4.dstAddr}, (bit<32>)CM_ROW);\
 sketch##num.read(meta.custom_metadata.count_val##num, meta.custom_metadata.hash_val##num); \
 meta.custom_metadata.count_val##num = meta.custom_metadata.count_val##num +1; \
 sketch##num.write(meta.custom_metadata.hash_val##num, meta.custom_metadata.count_val##num)



control MyVerifyChecksum(inout headers hdr, inout metadata meta) {
    apply {  }
}




control MyIngress(inout headers hdr,
                  inout metadata meta,
                  inout standard_metadata_t standard_metadata) {

    SKETCH_REGISTER(1);
    SKETCH_REGISTER(2);
    SKETCH_REGISTER(3);
    SKETCH_REGISTER(4);
    SKETCH_REGISTER(5);
    SKETCH_REGISTER(6);
    SKETCH_REGISTER(7);
    SKETCH_REGISTER(8);
    SKETCH_REGISTER(9);
    SKETCH_REGISTER(10);

    register<bit<32>>(1) packet_tot;
    register<bit<32>>(SAMPLELIST_SIZE) sampleList_src;
    register<bit<32>>(SAMPLELIST_SIZE) sampleList_dst;
    register<bit<32>>(SAMPLELIST_SIZE) sampleList_count;
    register<bit<32>>(3) hh_r;

// 0: srcAddr, 1: dstAddr, 2: count

    action drop() {
        mark_to_drop(standard_metadata);
    }

    action set_heavy_hitter_count() {
        SKETCH_COUNT(1, crc32_custom);
        SKETCH_COUNT(2, crc32_custom);
        SKETCH_COUNT(3, crc32_custom);
        SKETCH_COUNT(4, crc32_custom);
        SKETCH_COUNT(5, crc32_custom);
        SKETCH_COUNT(6, crc32_custom);
        SKETCH_COUNT(7, crc32_custom);
        SKETCH_COUNT(8, crc32_custom);
        SKETCH_COUNT(9, crc32_custom);
        SKETCH_COUNT(10, crc32_custom);
    }

    action do_copy_to_cpu() {
        clone_preserving_field_list(CloneType.I2E, CPU_MIRROR_SESSION_ID, FieldLists.redirect_FL);
    }

    action increment_tot() {
        packet_tot.read(meta.custom_metadata.count_tot,0);
        meta.custom_metadata.count_tot=meta.custom_metadata.count_tot+1;
        packet_tot.write(0,meta.custom_metadata.count_tot);
    }

    action do_read_tot() {
        packet_tot.read(meta.custom_metadata.sum,0);
    }

    action do_find_min1() {
        meta.custom_metadata.count_min=meta.custom_metadata.count_val1;
    }

    action do_find_min2() {
        meta.custom_metadata.count_min=meta.custom_metadata.count_val2;
    }

    action do_find_min3() {
        meta.custom_metadata.count_min=meta.custom_metadata.count_val3;
    }

    action do_find_min4() {
        meta.custom_metadata.count_min=meta.custom_metadata.count_val4;
    }

    action do_find_min5() {
        meta.custom_metadata.count_min=meta.custom_metadata.count_val5;
    }

    action do_find_min6() {
        meta.custom_metadata.count_min=meta.custom_metadata.count_val6;
    }

    action do_find_min7() {
        meta.custom_metadata.count_min=meta.custom_metadata.count_val7;
    }

    action do_find_min8() {
        meta.custom_metadata.count_min=meta.custom_metadata.count_val8;
    }

    action do_find_min9() {
        meta.custom_metadata.count_min=meta.custom_metadata.count_val9;
    }

    action do_find_min10() {
        meta.custom_metadata.count_min=meta.custom_metadata.count_val10;
    }

    action do_set_maxinum() {
        meta.heavy_hitter.srcAddr=hdr.ipv4.srcAddr;
        meta.heavy_hitter.dstAddr=hdr.ipv4.dstAddr;
        meta.heavy_hitter.count=meta.custom_metadata.count_min;
        hh_r.write(0,meta.heavy_hitter.srcAddr);
        hh_r.write(1,meta.heavy_hitter.dstAddr);
        hh_r.write(2,meta.heavy_hitter.count);
    }

    action do_read_packets() {
        packet_tot.read(meta.custom_metadata.count_tot,0);
        meta.custom_metadata.sample_threshold=meta.custom_metadata.count_tot*(W/THETA + 1/EPSILON_INVERSE)/K;
    }

    action do_read_hh_threshold() {
        packet_tot.read(meta.custom_metadata.count_tot,0);
        meta.custom_metadata.hh_threshold=meta.custom_metadata.count_tot*(W/THETA + 1/EPSILON_INVERSE);
    }

    action ipv4_forward(macAddr_t dstAddr, egressSpec_t port) {

        hdr.ethernet.srcAddr = hdr.ethernet.dstAddr;


//set the destination mac address that we got from the match in the table
        hdr.ethernet.dstAddr = dstAddr;


//set the output port that we also get from the table
        standard_metadata.egress_spec = port;


//decrease ttl by 1
        hdr.ipv4.ttl = hdr.ipv4.ttl -1;

    }

    action do_read_max_count() {
        hh_r.read(meta.custom_metadata.count_max,2);
    }

    action do_read_max_count_final() {
        hh_r.read(meta.custom_metadata.count_max_final,2);
    }

    action do_check_sampleList() {
        hash(meta.custom_metadata.sample_hash_value,HashAlgorithm.crc32,(bit<16>)0,{hdr.ipv4.srcAddr,hdr.ipv4.dstAddr},(bit<32>)SAMPLELIST_SIZE);
        sampleList_count.read(meta.custom_metadata.current_count, meta.custom_metadata.sample_hash_value);
    }

    action do_add_sampleList() {
        sampleList_src.write(meta.custom_metadata.sample_hash_value,hdr.ipv4.srcAddr);
        sampleList_dst.write(meta.custom_metadata.sample_hash_value,hdr.ipv4.dstAddr);
        sampleList_count.write(meta.custom_metadata.sample_hash_value, meta.custom_metadata.count_min);
    }

    table ipv4_lpm {
        key = {
            hdr.ipv4.dstAddr: lpm;
        }
        actions = {
            ipv4_forward;
            drop;
            NoAction;
        }
        size = 1024;
        default_action = NoAction();
    }

    apply {
        do_read_tot();
        if(meta.custom_metadata.sum >= MAXIMUM_PACKETS){
            do_read_hh_threshold();
            do_read_max_count_final();
            if(meta.custom_metadata.count_max_final > meta.custom_metadata.hh_threshold){
                do_copy_to_cpu();
            }
        }
        increment_tot();
        ipv4_lpm.apply();
        set_heavy_hitter_count();
        do_find_min1();
        if(meta.custom_metadata.count_min > meta.custom_metadata.count_val2){
                do_find_min2();
        }
        if(meta.custom_metadata.count_min > meta.custom_metadata.count_val3){
                do_find_min3();
        }
        if(meta.custom_metadata.count_min > meta.custom_metadata.count_val4){
                do_find_min4();
        }
        if(meta.custom_metadata.count_min > meta.custom_metadata.count_val5){
                do_find_min5();
        }
        if(meta.custom_metadata.count_min > meta.custom_metadata.count_val6){
                do_find_min6();
        }
        if(meta.custom_metadata.count_min > meta.custom_metadata.count_val7){
                do_find_min7();
        }
        if(meta.custom_metadata.count_min > meta.custom_metadata.count_val8){
                do_find_min8();
        }
        if(meta.custom_metadata.count_min > meta.custom_metadata.count_val9){
                do_find_min9();
        }
        if(meta.custom_metadata.count_min > meta.custom_metadata.count_val10){
                do_find_min10();
        }
        do_read_packets();
        if(meta.custom_metadata.count_min > MIN&&meta.custom_metadata.count_min > meta.custom_metadata.sample_threshold){
            do_check_sampleList();
            if(meta.custom_metadata.current_count < meta.custom_metadata.count_min){
                do_add_sampleList();
                do_read_max_count();
                if(meta.custom_metadata.count_min > meta.custom_metadata.count_max){
                    do_set_maxinum();
                }
            }
        }
    }
}



control MyEgress(inout headers hdr,
                 inout metadata meta,
                 inout standard_metadata_t standard_metadata) {
    apply {
        if(standard_metadata.instance_type == 0x01) {
            hdr.cpu_header.setValid();
            hdr.cpu_header.flag=1;
        }
    }
}



control MyComputeChecksum(inout headers hdr, inout metadata meta) {
     apply {
        update_checksum(
            hdr.ipv4.isValid(),
            { hdr.ipv4.version,
              hdr.ipv4.ihl,
              hdr.ipv4.diffserv,
              hdr.ipv4.totalLen,
              hdr.ipv4.identification,
              hdr.ipv4.flags,
              hdr.ipv4.fragOffset,
              hdr.ipv4.ttl,
              hdr.ipv4.protocol,
              hdr.ipv4.srcAddr,
              hdr.ipv4.dstAddr },
            hdr.ipv4.hdrChecksum,
            HashAlgorithm.csum16);
    }
}




control MyDeparser(packet_out packet, in headers hdr) {
    apply {
        packet.emit(hdr.cpu_header);
        packet.emit(hdr.ethernet);
        packet.emit(hdr.ipv4);
        packet.emit(hdr.tcp);
        packet.emit(hdr.udp);
    }
}




//switch architecture
V1Switch(
MyParser(),
MyVerifyChecksum(),
MyIngress(),
MyEgress(),
MyComputeChecksum(),
MyDeparser()
) main;

#include <core.p4>
#include <v1model.p4>

#define WRITE_REG(r, v) r.write((bit<32>)standard_metadata.egress_port, v);
#define READ_REG(r, v) r.read(v,(bit<32>)standard_metadata.egress_port);
#define CAP(c, v, a, t){ if (v > c) a = c; else a = (t)v; }

const bit<16> TYPE_IPV4 = 0x800;
const bit<32> MAX_RND = 0xFFFFFFFF;



typedef bit<9>  egressSpec_t;
typedef bit<48> macAddr_t;
typedef bit<32> ip4Addr_t;

//input parameters
typedef int<32> alpha_t;
typedef int<32> beta_t;
typedef int<32> delay_t;
typedef bit<5> interval_t;

//state registers
register<bit<48>>(256) r_update_time;

// timestamp of previous PI calculation
register<int<32>>(256) r_queue_delay;

// queue delay at previous PI calculation
register<bit<32>>(256) r_probability;

// probability at previous PI calculation

header ethernet_t {
    macAddr_t dst_addr;
    macAddr_t src_addr;
    bit<16>   etherType;
}

header ipv4_t {
    bit<4>    version;
    bit<4>    ihl;
    bit<8>    diffserv;
    bit<16>   totalLen;
    bit<16>   identification;  
    bit<3>    flags;
    bit<13>   fragOffset;
    bit<8>    ttl;
    bit<8>    protocol;
    bit<16>   hdrChecksum;
    ip4Addr_t srcAddr;
    ip4Addr_t dstAddr;
}

header udp_t {
    bit<16> sourcePort;
    bit<16> destPort;
    bit<16> length_;
    bit<16> checksum;
}

header tcp_t {
    bit<16> srcPort;
    bit<16> dstPort;
    bit<32> seqNo;
    bit<32> ackNo;
    bit<4>  dataOffset;
    bit<4>  res;
    bit<8>  flags;
    bit<16> window;
    bit<16> checksum;
    bit<16> urgentPtr;
}

struct metadata {
    bit<1>   mark_drop;
    bit<16>  tcpLength;
}

struct headers {
    ethernet_t   ethernet;
    ipv4_t       ipv4;
    tcp_t         tcp;  
    udp_t         udp;
}

error { IPHeaderTooShort }



parser MyParser(packet_in packet,
                  out headers hdr,
                  inout metadata meta,
                  inout standard_metadata_t standard_metadata) {

    state start {
        transition parse_ethernet;
    }

    state parse_ethernet {
        packet.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType) {
            TYPE_IPV4: parse_ipv4;
            default: accept;
        }
    }

    state parse_ipv4 {
        packet.extract(hdr.ipv4);
        transition select(hdr.ipv4.protocol) {
            8w17: parse_udp;
            8w6: parse_tcp;
            default: accept;
        }
    }

    state parse_tcp {
        packet.extract(hdr.tcp);
        transition accept;
    }

    state parse_udp {
        packet.extract(hdr.udp);
	    transition accept;
    }
}




