control MyIngress(inout headers hdr,
                  inout metadata meta,
                  inout standard_metadata_t standard_metadata) {
    action drop() {
        mark_to_drop(standard_metadata);

    }

    action forward(bit<9> egress_spec, bit<48> dst_mac) {
        standard_metadata.egress_spec = egress_spec;
        hdr.ethernet.dst_addr = dst_mac;
    }
    table forwarding {
        actions = {
            forward;
        }
        key = {
            standard_metadata.ingress_port: exact;
            hdr.ipv4.dstAddr              : exact;
        }
    }

    apply {
        if (hdr.ipv4.isValid()) {
            forwarding.apply();
        }
    }
}



control MyEgress(inout headers hdr,
                 inout metadata meta,
                 inout standard_metadata_t standard_metadata){
    action drop() {
        mark_to_drop(standard_metadata);
    }


    action pi2(alpha_t alpha, beta_t beta, delay_t target, interval_t interval){
        bit<48> last_update_time = 0;
        int<32> last_queue_delay;
        bit<32> last_probability;

        READ_REG(r_update_time, last_update_time);

        READ_REG(r_queue_delay, last_queue_delay);

        READ_REG(r_probability, last_probability);

// read last calculated PI probability


// initialization - no previous update time
        if (last_update_time == 0) {
            last_update_time = standard_metadata.egress_global_timestamp;
        }

        bit<32> update_laps = (bit<32>) ((standard_metadata.egress_global_timestamp - last_update_time) >> interval); 

        if (update_laps >= 1){
            if (update_laps >= 2000) update_laps = 2000;


            int<32> prev_queue_delay = last_queue_delay;

// preserve previous queue delay
            CAP(1000000, standard_metadata.deq_timedelta, last_queue_delay, int<32>);

// update and cap queueing delay to 1s


// calculate change in probability;  subtract extra alpha.TARGET for every extra lap Q assumed 0
            int<32> delta = (last_queue_delay - (int<32>)update_laps * target) * alpha + (last_queue_delay - prev_queue_delay) * beta;
            bit<33> new_probability = (bit<33>) last_probability;

// add one bit to detect under- and overflows
            new_probability = (bit<33>) ((int<33>) new_probability + (int<33>) delta);

// delta needs sign preservation
            if (new_probability > (bit<33>)MAX_RND) {

// check for under- and overflows
                if (delta > 0) last_probability = MAX_RND;
                else last_probability = 0;
            } else last_probability = (bit<32>) new_probability;

// otherwise update latest probability

            last_update_time = standard_metadata.egress_global_timestamp;

        }


//update registers
        WRITE_REG(r_probability, last_probability);

// store new drop probability
        WRITE_REG(r_queue_delay, last_queue_delay);

// store delay
        WRITE_REG(r_update_time, last_update_time);


        bit<32> rnd;
        random(rnd,0,MAX_RND);
        if ((rnd < last_probability) && ((rnd << 16) < last_probability))

// squaring by using 16 lsb as second independent random value
            meta.mark_drop = 1; 

    }


    table aqm{
        key = {
            standard_metadata.egress_port: exact;
        }    
        actions = {
            pi2();
            NoAction;
        }
        default_action = NoAction; 
    }


    apply {
        meta.tcpLength = hdr.ipv4.totalLen;
        meta.tcpLength = meta.tcpLength-20;
        aqm.apply();    
        if (meta.mark_drop == 1) {
            drop();
        } 
    }

}



control MyComputeChecksum(inout headers hdr, inout metadata meta) {
    apply {
        update_checksum(
            hdr.ipv4.isValid(), 
            { hdr.ipv4.version, 
            hdr.ipv4.ihl, 
            hdr.ipv4.diffserv, 
            hdr.ipv4.totalLen, 
            hdr.ipv4.identification, 
            hdr.ipv4.flags, 
            hdr.ipv4.fragOffset, 
            hdr.ipv4.ttl, 
            hdr.ipv4.protocol, 
            hdr.ipv4.srcAddr, 
            hdr.ipv4.dstAddr }, 
            hdr.ipv4.hdrChecksum, 
            HashAlgorithm.csum16);
        update_checksum_with_payload(
            hdr.tcp.isValid(), 
            { hdr.ipv4.srcAddr, 
            hdr.ipv4.dstAddr, 
            8w0, 
            hdr.ipv4.protocol, 
            meta.tcpLength, 
            hdr.tcp.srcPort, 
            hdr.tcp.dstPort, 
            hdr.tcp.seqNo, 
            hdr.tcp.ackNo, 
            hdr.tcp.dataOffset, 
            hdr.tcp.res, 
            hdr.tcp.flags, 
            hdr.tcp.window, 
            hdr.tcp.urgentPtr}, 
            hdr.tcp.checksum, 
            HashAlgorithm.csum16);
    }
}



control MyDeparser(packet_out packet, in headers hdr) {
    apply {
        packet.emit(hdr.ethernet);
        packet.emit(hdr.ipv4);
        packet.emit(hdr.tcp);
        packet.emit(hdr.udp);
    }
}



V1Switch(
MyParser(),
MyVerifyChecksum(),
MyIngress(),
MyEgress(),
MyComputeChecksum(),
