#ifndef _PARSER_
#define _PARSER_

parser SwitchParser(
            packet_in pkt,
            out Header hdr,
            inout UserMetadata user_md,
            inout standard_metadata_t st_md) {

    state start {
        transition parse_ethernet;
    }

    state parse_ethernet {
        pkt.extract(hdr.ether);
        transition select(hdr.ether.etherType) {
            ETH_P_VLAN : parse_vlan;
            ETH_P_IPV4 : parse_ipv4;
            ETH_P_IPV6 : parse_ipv6;
            default : accept;
        }
    }
    state parse_vlan {
        pkt.extract(hdr.vlan_tag);
        transition select(hdr.vlan_tag.etherType) {
            ETH_P_IPV4 : parse_ipv4;
            ETH_P_IPV6 : parse_ipv6;
            default : accept;
        }
    }
    state parse_ipv4 {
        pkt.extract(hdr.ipv4);
        transition select(hdr.ipv4.protocol) {
            IPPROTO_TCP : parse_tcp;
            IPPROTO_UDP : parse_udp;
            default : accept;
        }
    }
    state parse_ipv6 {
        pkt.extract(hdr.ipv6);
        transition select(hdr.ipv6.nextHdr) {
            IPPROTO_TCP : parse_tcp;
            IPPROTO_UDP : parse_udp;
            default : accept;
        }
    }
    state parse_tcp {
        pkt.extract(hdr.tcp);
        transition accept;
    }
    state parse_udp {
        pkt.extract(hdr.udp);
        transition select(hdr.udp.dstPort) {
            default: accept;
        }
    }
}

control SwitchDeparser(
            packet_out pkt,
            in Header hdr) {

    apply {
        pkt.emit(hdr.ether);
        pkt.emit(hdr.vlan_tag);
        pkt.emit(hdr.ipv6);
        pkt.emit(hdr.ipv4);
        pkt.emit(hdr.icmp);
        pkt.emit(hdr.tcp);
        pkt.emit(hdr.udp);
    }
}

#endif

control PortMap(
        inout Header hdr,
        inout IngressMetadata ig_md,
        inout standard_metadata_t st_md) {

    apply {
        if (hdr.vlan_tag.isValid()) {
            ig_md.vlan_pcp = hdr.vlan_tag.pcp;
            ig_md.vlan_dei = hdr.vlan_tag.dei;
            ig_md.vlan_id = hdr.vlan_tag.vid;
            ig_md.etherType = hdr.vlan_tag.etherType;
            ig_md.is_tagged = 1;
        } else {
            ig_md.etherType = hdr.ether.etherType;
        }
    }
}

control PortMapEgress(
        inout Header hdr,
        inout UserMetadata user_md,
        inout standard_metadata_t st_md) {

    action vlan_tagged() {
        hdr.ether.etherType = ETH_P_VLAN;
        hdr.vlan_tag.setValid();
        hdr.vlan_tag.pcp = user_md.ig_md.vlan_pcp;
        hdr.vlan_tag.dei = user_md.ig_md.vlan_dei;
        hdr.vlan_tag.vid = user_md.ig_md.vlan_id;
        hdr.vlan_tag.etherType = user_md.ig_md.etherType;
    }
    action vlan_untagged() {
        hdr.ether.etherType = user_md.ig_md.etherType;
        hdr.vlan_tag.setInvalid();
    }
    action vlan_unassigned() {
        vlan_untagged();
    }

    apply {
        if (user_md.ig_md.is_tagged == 1){
            vlan_untagged();
        }else{
            vlan_tagged();
        }
    }
}

control PortFwd(
        in PortId_t in_port,
        inout PortId_t egress_port,
        inout bit<16> mcast_grp) {


    action set_egress_port(PortId_t port) {
        egress_port = port;

        mcast_grp = 0;
    }

    table portfwd {
        key = {
            in_port: exact;

// ingress phy port
        }
        actions = {
            set_egress_port;
        }
    }

    apply {
        portfwd.apply();
    }
}

control L2Fwd(
    in EthernetAddress ether_dst_addr,
    in EthernetAddress ether_src_addr,
    inout IngressMetadata ig_md,
    inout standard_metadata_t st_md)
    (bit<32> table_size_dmac) {

    action smac_miss() {

    }
    action smac_hit() {
        NoAction();
    }
    table smac {
        key = {
            ether_src_addr : exact;
            st_md.ingress_port : exact;
        }
        actions = {
            smac_miss;
            smac_hit;
        }
        const default_action = smac_miss;
    }
    action dmac_miss() {
        ig_md.flood = 1;
    }
    action dmac_hit(PortId_t port) {
        st_md.egress_spec = port;
    }

    table dmac {
        key = {
            ether_dst_addr : exact;
        }
        actions = {
            dmac_miss;
            dmac_hit;
        }
        const default_action = dmac_miss();
        size = table_size_dmac;
    }

    apply {
        smac.apply();
        dmac.apply();
    }
}

control Navt(
    inout EthernetAddress ether_src_addr,
    inout EthernetAddress ether_dst_addr,
    inout IPv4Address ip_src_addr,
    inout IPv4Address ip_dst_addr,
    inout IngressMetadata ig_md,
    inout standard_metadata_t st_md)
    () {
    apply {
        if (ig_md.etherType == ETH_P_IPV4) {

// dst is 192.168.0.0/16 is not work
            if (ip_dst_addr[8:0] == 10 && ip_dst_addr[16:9] == 168){
                mark_to_drop(st_md);
                return;
            }

            if (ip_dst_addr[31:24] == 10 && 1 <= ip_dst_addr[31:24] && ip_dst_addr[31:24] <= 15){
                if (ip_src_addr[31:24] == 10 && 1 <= ip_src_addr[31:24] && ip_src_addr[31:24] <= 15) {
                    return;
                }

// to external nat
                ip_dst_addr[31:24] = 192;


                ig_md.vlan_id = (bit<12>)((ip_dst_addr[23:16]<<5)+(ip_dst_addr[23:16]<<6)+(ip_dst_addr[23:16]<<2));
                ip_dst_addr[23:16] = 168;
                if (ig_md.vlan_id == 100){
                    ether_dst_addr = 0x020304050611;
                    ether_src_addr = 0x0203040506fe;
                }else if(ig_md.vlan_id == 200){
                    ether_dst_addr = 0x020304050622;
                    ether_src_addr = 0x0203040506fe;
                }
            } else {

// to internal nat
                ip_src_addr[31:24] = 10;
                if (ig_md.vlan_id ==100){
                    ip_src_addr[23:16] = 1;
                }else if(ig_md.vlan_id == 200){
                    ip_src_addr[23:16] = 2;
                }

                ether_dst_addr = 0x020304050601;
                ether_src_addr = 0x0203040506fe;
            }
        }
    }
}



// CONTROL: INGRESS 

control SwitchIngress(
            inout Header hdr,
            inout UserMetadata user_md,
            inout standard_metadata_t st_md) {

    PortMap() portmap;
    L2Fwd(1024) l2fwd;
    Navt() navt;


    apply {
        mark_to_drop(st_md);
        portmap.apply(hdr, user_md.ig_md, st_md);

        navt.apply(hdr.ether.srcAddr, hdr.ether.dstAddr, hdr.ipv4.srcAddr, hdr.ipv4.dstAddr, user_md.ig_md, st_md);
        l2fwd.apply(hdr.ether.dstAddr, hdr.ether.srcAddr, user_md.ig_md, st_md);
    }
}


// CONTROL: EGRESS 

control SwitchEgress(
            inout Header hdr,
            inout UserMetadata user_md,
            inout standard_metadata_t st_md) {

    action drop() {
        mark_to_drop(st_md);
    }

    PortMapEgress() portmap_egress;

    apply {

// drop flood packet going back to incoming port
        if(st_md.ingress_port == st_md.egress_port && user_md.ig_md.flood == 1) {
            drop();
        }
        portmap_egress.apply(hdr, user_md, st_md);
    }
}


// CONTROL: CHECKSUM 

control NoSwitchVerifyChecksum(
            inout Header hdr,
            inout UserMetadata user_md) {

// dummy control to skip checkum
    apply { }
}
control SwitchVerifyChecksum(
            inout Header hdr,
            inout UserMetadata user_md) {
    apply {
        verify_checksum(hdr.ipv4.isValid() && hdr.ipv4.ihl == 5,
            { hdr.ipv4.version,
                hdr.ipv4.ihl,
                hdr.ipv4.diffserv,
                hdr.ipv4.totalLen,
                hdr.ipv4.identification,
                hdr.ipv4.flags,
                hdr.ipv4.fragOffset,
                hdr.ipv4.ttl,
                hdr.ipv4.protocol,
                hdr.ipv4.srcAddr,
                hdr.ipv4.dstAddr },
            hdr.ipv4.hdrChecksum, HashAlgorithm.csum16);
    }
}
control NoSwitchComputeChecksum(
            inout Header hdr,
            inout UserMetadata user_md) {

// dummy control to skip checkum
    apply { }
}
control SwitchComputeChecksum(
            inout Header hdr,
            inout UserMetadata user_md) {
    apply {
        update_checksum(hdr.ipv4.isValid() && hdr.ipv4.ihl == 5,
            { hdr.ipv4.version,
                hdr.ipv4.ihl,
                hdr.ipv4.diffserv,
