typedef bit<48> macAddr_t;
typedef bit<128> ip6Addr_t;


#define CPU_PORT 255
#define MAX_HEADER 8
const bit<16> ETHERTYPE_IPV6 = 0x86dd;
const bit<8>  IP_PROTO_ICMPV6 = 58;
const bit<8>  IP_PROTO_TCP = 6;
const bit<8>  IP_PROTO_UDP = 17;
const bit<8>  IP_NO_NXT = 59;
const bit<8>  IP_EH_HBH = 0;
const bit<8>  IP_EH_ROUTING = 43;
const bit<8>  IP_EH_FRAGMENT = 44;
const bit<8>  IP_EH_DEST_OPTIONS = 60;
const bit<8>  ICMPV6_TYPE_RA = 134;
const bit<8>  NDP_SOURCE_OPTION = 1;
const bit<8>  NDP_TARGET_OPTION = 2;
const bit<8>  NDP_PREFIX_OPTION = 3;
const bit<8>  NDP_REDIRECT_OPTION = 4;
const bit<8>  NDP_MTU_OPTION = 5;
const macAddr_t MCAST_MASK = 0xFF_FF_00_00_00_00;
const macAddr_t IPV6_MCAST = 0x33_33_00_00_00_00;
const bit<10> LINK_LOCAL = 0x3FA;

header ethernet_t {
    macAddr_t dstAddr;
    macAddr_t srcAddr;
    bit<16>   etherType;
}

header ipv6_t {
    bit<4>    version;
    bit<8>    traffic_class;
    bit<20>   flow_label;
    bit<16>   payload_len;
    bit<8>    next_hdr;
    bit<8>    hop_limit;
    ip6Addr_t srcAddr;
    ip6Addr_t dstAddr;
}

header hop_by_hop_t {
    bit<8>      next_hdr;
    bit<8>      length;

// totallength: (length+1) * 8Byte
    varbit<1024> options;
}

struct next_extension_header {
    bit<8>      next_hdr;
    bit<8>      length;
}

header routing_t {
    bit<8>      next_hdr;
    bit<8>      length;

// totallength: (length+1) * 8Byte
    bit<8>      type;
    bit<8>      segments;

    varbit<1024> data;
}

header fragment_t {
    bit<8>    next_hdr;
    bit<8>    reserved;
    bit<13>   offset;

// Offset, in 8B units, relative to the start of the fragmentable part of the original packet.
    bit<2>    res;
    bit<1>    m_flag;

    bit<32>   identification;
}

header dest_options_t {
    bit<8>       next_hdr;
    bit<8>       length;

    varbit<1024>  options;
}

header icmpv6_t {
    bit<8>   type;
    bit<8>   code;
    bit<16>  checksum;
}

header ndp_ra_t {
    bit<8>       hop_limit;
    bit<2>       flags;
    bit<6>       reserved;
    bit<16>      lifetime;
    bit<32>      reachable_time;
    bit<32>      retrans_timer;
}

header ndp_ll_addr_t {
    bit<8>       type;
    bit<8>       length;
    macAddr_t    Addr;
}

header ndp_prefix_t {
    bit<8>       type;
    bit<8>       length;
    bit<8>       prefix_length;
    bit<2>       flags;
    bit<6>       reserved;
    bit<32>      valid_lifetime;
    bit<32>      preferred_lifetime;
    bit<32>      prefix_reserved;
    ip6Addr_t    prefix;
}

header ndp_redirect_t {
    bit<8>       type;
    bit<8>       length;
    bit<16>      reserved;
    bit<128>     original_pkt;

    ip6Addr_t    prefix;
}

header ndp_mtu_t {
    bit<8>       type;
    bit<8>       length;
    bit<16>      reserved;
    bit<32>      mtu;
}

struct eh_counter_t {
    bit<8>     hbh;
    bit<8>     routing;
    bit<8>     fragment;
    bit<8>     dest_options;
}

struct metadata_t {
    bool            is_multicast;
    bool            is_blocked;
    bit<8>          next_hdr;
