const bit<5>  TYPE_TO1518 = 0x07;

const bit<32> MIN_VALUE = 0x0;
const bit<32> MAX_VALUE = 10000;






typedef bit<48> time_t;
typedef bit<48> macAddr_t;

header ethernet_t {
    macAddr_t dstAddr;
    macAddr_t srcAddr;
    bit<16>   etherType;
}

header ipv6_t {
    bit<4>    version;
    bit<8>    trafClass;
    bit<20>   flowLabel;
    bit<16>   payloadLen;
    bit<8>    nextHeader;
    bit<8>    hopLimit;
    bit<128>  srcAddr;
    bit<128>  dstAddr;
}

header bits_t{
    bit<1>    delay;
    bit<1>    loss;
    bit<1>    notification;
    bit<5>    padding;
}


struct metadata {
    bit<1>    generate;
    bit<9>    out_port;
    bit<10>   time;
    bit<16>   delay_select;
}


struct headers {
    ethernet_t   ethernet;
    ipv6_t       ipv6;
    bits_t       bits;

}




parser MyParser(packet_in packet,
                out headers hdr,
                inout metadata meta,
                inout standard_metadata_t standard_metadata) {

    state start {
        transition parse_ethernet;
    }

    state parse_ethernet {
        packet.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType) {
            TYPE_IPV6: parse_ipv6;
            default: accept;
        }
    }

    state parse_ipv6 {
        packet.extract(hdr.ipv6);
        transition select(hdr.ipv6.nextHeader) {
            TYPE_BITS: parse_bits;
            default: accept;
        }
    }

    state parse_bits{
        packet.extract(hdr.bits);
        transition accept;
    }



}



