        curr_time = standard_metadata.ingress_global_timestamp;
        timer.write(index, curr_time);
    }

    action time_compute(bit<32> index){
        timer.read(time_check, index);
        curr_time = standard_metadata.ingress_global_timestamp;
        elapsed_time = curr_time - time_check;
    }



