control IngressPipeImpl (inout parsed_headers_t hdr,
                        inout local_metadata_t local_metadata,
                        inout standard_metadata_t standard_metadata) {

    action drop() {
	mark_to_drop(standard_metadata);
    }

    action set_output_port(port_num_t port_num) {
        standard_metadata.egress_spec = port_num;
    }

    action set_next_hop(mac_addr_t next_hop, bit<1> ttl_w) {
	hdr.ethernet.src_addr = hdr.ethernet.dst_addr;
	hdr.ethernet.dst_addr = next_hop;
	if ( ttl_w == 1) {
		hdr.ipv4.ttl = hdr.ipv4.ttl - 1;
	}
    }

    action set_next_hop_wTun(mac_addr_t next_hop, bit<1> ttl_w, bit<16> dst_id) {
	hdr.ethernet.src_addr = hdr.ethernet.dst_addr;
	hdr.ethernet.dst_addr = next_hop;
	if ( ttl_w == 1) {
		hdr.ipv4.ttl = hdr.ipv4.ttl - 1;
	}

	hdr.ethernet.ethtype = ETHERTYPE_TUN;
	hdr.tun.setValid();
	hdr.tun.proto_id =  ETHERTYPE_IPV4;
	hdr.tun.dst_id = dst_id;
    }

    action set_local_broadcast() {
        local_metadata.is_multicast = true;
        standard_metadata.mcast_grp = 0x1;
    }

    table myTunnel_table {
            key = {
                hdr.tun.dst_id: exact;
            }
            actions = {
		NoAction;
            }
	    size = 128;
          default_action = NoAction();
      }

    table tun_forwarding_table {
            key = {
                hdr.tun.dst_id: exact;
            }
            actions = {
              set_output_port;
	      drop;
            }
	    size = 1024;
          default_action = drop();
      }

    table l2_unicast_table {
            key = {
                hdr.ethernet.dst_addr: exact;
            }
            actions = {
              set_output_port;
              NoAction;
            }
	    size = 1024;
          default_action = NoAction();
      }

    table my_mac_addresses_table {
            key = {
                hdr.ethernet.dst_addr: exact;
            }
            actions = {
              NoAction;
            }
	    size = 128;
          default_action = NoAction();
      }

    table l3_forwarding_table {
            key = {
                hdr.ipv4.dst_addr: lpm;
            }
            actions = {
	      set_next_hop;
	      set_next_hop_wTun;
              NoAction;
            }
	    size = 1024;
          default_action = NoAction();
      }

    table arp_cache_table {
            key = {
                hdr.ipv4.dst_addr: exact;
            }
            actions = {
	      set_next_hop;
              NoAction;
            }
	    size = 1024;
          default_action = NoAction();
      }

    apply {

	if (hdr.tun.isValid()) {
		if ( !myTunnel_table.apply().hit ) {
			tun_forwarding_table.apply();
		}
		else {
			hdr.tun.setInvalid();
			hdr.ethernet.ethtype = ETHERTYPE_IPV4;
		}
	}

	if (hdr.ipv4.isValid() && !hdr.tun.isValid()) {
		if ( my_mac_addresses_table.apply().hit ) {
			l3_forwarding_table.apply();
			arp_cache_table.apply();
		}
	}

	if  (!l2_unicast_table.apply().hit) {
		set_local_broadcast();
	}

    }
}

V1Switch(
    ParserImpl(),
    VerifyChecksumImpl(),
    IngressPipeImpl(),
    EgressPipeImpl(),
    ComputeChecksumImpl(),
    DeparserImpl()

) main;

