typedef bit<48>  EthernetAddress;
typedef bit<32>  IPv4Address;
typedef bit<128> IPv6Address;


header ethernet_h {
    EthernetAddress dst_addr;
    EthernetAddress src_addr;
    etype_t ether_type;
}


header vlan_tag_h {
    bit<3>  pcp;

// priority code point
    bit<1>  dei;

    bit<12> vid;

// VLAN identifier
    etype_t ether_type;
}


header mpls_h {
    bit<20> label;
    bit<3>  tc;

// traffic class.  Formerly EXP (before 2009, RFC 5462)
    bit<1>  bos;

// bottom of stack
    bit<8>  ttl;

// time to live
}


header ipv4_h {
    bit<4>  version;

// always 4 for IPv4
    bit<4>  ihl;

// Internet header length
    bit<8>  diffserv;

// 6 bits of DSCP followed by 2-bit ECN
    bit<16> total_len;

// in bytes, including IPv4 header
    bit<16> identification;
    bit<3>  flags;

    bit<13> frag_offset;
    bit<8>  ttl;

// time to live
    ipproto_t protocol;
    bit<16> hdr_checksum;
    IPv4Address src_addr;
    IPv4Address dst_addr;
}


header ipv6_h {
    bit<4>  version;
    bit<8>  traffic_class;
    bit<20> flow_label;
    bit<16> payload_len;
    ipproto_t next_hdr;
    bit<8>  hop_limit;
    IPv6Address src_addr;
    IPv6Address dst_addr;
}


// Segment Routing Extension (SRH) -- IETFv7
header ipv6_srh_h {
    ipproto_t next_hdr;
    bit<8>  hdr_ext_len;
    bit<8>  routing_type;
    bit<8>  seg_left;
    bit<8>  last_entry;
    bit<8>  flags;
    bit<16> tag;
}


header arp_h {

    bit<16> hw_type;

    bit<16> proto_type;
    bit<8>  hw_addr_len;
    bit<8>  proto_addr_len;
    bit<16> opcode;

// ...
}

header arp_rarp_ipv4_h {
    bit<48> src_hw_addr;
    IPv4Address src_proto_addr;
    bit<48> dst_hw_addr;
    IPv4Address dst_proto_addr;
}


header icmp_h {
    bit<8>  type;
    bit<8>  code;
    bit<16> checksum;

// ICMP Payload follows, but not parsing
}


header udp_h {
    bit<16> src_port;
    bit<16> dst_port;
    bit<16> length;
    bit<16> checksum;
}


header tcp_h {
    bit<16> src_port;
    bit<16> dst_port;
    bit<32> seq_no;
    bit<32> ack_no;
    bit<4>  data_offset;
