header sctp_h {
    bit<16> src_port;
    bit<16> dst_port;
    bit<32> verif_tag;
    bit<32> checksum;
}


header igmp_h {
    bit<8>  type;
    bit<8>  code;
    bit<16> checksum;

// ...
}


header vxlan_h {
    bit<8>  flags;
    bit<24> reserved;
    bit<24> vni;
    bit<8>  reserved2;
}


header vxlan_gpe_h {
    bit<8>  flags;
    bit<16> reserved;

    bit<8>  next_proto;
    bit<24> vni;
    bit<8>  reserved2;
}


header gre_h {
    bit<1>  C;
    bit<12> reserved0;
    bit<3>  version;

    bit<16> proto;

// Omit variable length portions.
}


