struct headers_t {
    ethernet_h    ethernet;
}

struct metadata_t {
}

parser ingressParserImpl(
    packet_in pkt,
    out headers_t hdr,
    inout metadata_t umd,
    inout standard_metadata_t stdmeta)
{
    state start {
        pkt.extract(hdr.ethernet);
        transition accept;
    }
}

control verifyChecksum(
    inout headers_t hdr,
    inout metadata_t umd)
{
    apply { }
}

control ingressImpl(
    inout headers_t hdr,
    inout metadata_t umd,
    inout standard_metadata_t stdmeta)
{
    bit<8> ret1 = 0;
    action my_drop() {
        mark_to_drop(stdmeta);
    }
    action t1_a1() {
        hdr.ethernet.src_addr[7:0] = 1;
    }
    action t1_a2() {
        hdr.ethernet.src_addr[7:0] = 2;
        exit;
    }
    table t1 {
        key = { hdr.ethernet.dst_addr[7:0] : exact; }
        actions = { t1_a1; t1_a2; NoAction; }
        const default_action = NoAction;
    }
    action t2_a1() {
        hdr.ethernet.src_addr[7:0] = 3;
    }
    action t2_a2() {
        hdr.ethernet.src_addr[7:0] = 4;
        exit;
    }
    table t2 {
        key = { hdr.ethernet.dst_addr[15:8] : exact; }
        actions = { t2_a1; t2_a2; NoAction; }
        const default_action = NoAction;
    }
    apply {
        if (hdr.ethernet.isValid()) {
            if (t1.apply().hit && t2.apply().hit) {
                ret1 = 1;
            } else {
                ret1 = 2;
            }
            hdr.ethernet.src_addr[15:8] = ret1;
        }
    }
}

control egressImpl(
    inout headers_t hdr,
    inout metadata_t umd,
    inout standard_metadata_t stdmeta)
{
    apply { }
}

control updateChecksum(
    inout headers_t hdr,
    inout metadata_t umd)
{
    apply { }
}

control egressDeparserImpl(
    packet_out pkt,
    in headers_t hdr)
{
    apply {
        pkt.emit(hdr.ethernet);
    }
}

V1Switch(ingressParserImpl(),
         verifyChecksum(),
         ingressImpl(),
         egressImpl(),
         updateChecksum(),
         egressDeparserImpl()) main;

