control packet_in_encap(inout headers_t headers,
                        inout local_metadata_t local_metadata,
                        inout standard_metadata_t standard_metadata) {
  apply {
#if defined(PLATFORM_BMV2) || defined(PLATFORM_P4SYMBOLIC)
