    arp_tpa::mask != 0 -> ether_type == 0x0806;
#endif
#if defined(SAI_INSTANTIATION_FABRIC_BORDER_ROUTER) || defined(SAI_INSTANTIATION_TOR)

    icmp_type::mask != 0 -> ip_protocol == 1;
