        }, hdr.inner_ipv4.hdrChecksum, HashAlgorithm.csum16);

        update_checksum(hdr.ipv4.ihl == 5, {

            hdr.ipv4.version,
            hdr.ipv4.ihl,
            hdr.ipv4.diffserv,
            hdr.ipv4.totalLen,
