control Bcast_egress(
    inout headers hdr,
    inout metadata meta,
    inout standard_metadata_t standard_metadata
){
    action rewrite_mac(bit<48> smac){
        hdr.ethernet.srcAddr = smac;
    }

    action _drop(){
        mark_to_drop(standard_metadata);
    }

    table send_frame{
        actions = {
            rewrite_mac;
            _drop;
            NoAction;
        }
        key = {
            standard_metadata.egress_port: exact;
        }
        size = 256;
        default_action = NoAction();
    }

    apply {
        if(hdr.ipv4.isValid()){
            send_frame.apply();
        }
    }
}


// compute checksum
control Bcast_computeChecksum(
    inout headers hdr, inout metadata meta
){
    apply {
        update_checksum(
            hdr.ipv4.isValid(),
            { hdr.ipv4.version, hdr.ipv4.ihl, hdr.ipv4.dscp, hdr.ipv4.ecn,
            hdr.ipv4.totalLen, hdr.ipv4.identification,
            hdr.ipv4.flags, hdr.ipv4.fragOffset, hdr.ipv4.ttl,
            hdr.ipv4.protocol, hdr.ipv4.srcAddr, hdr.ipv4.dstAddr },
            hdr.ipv4.hdrChecksum,
            HashAlgorithm.csum16);
    }
}


// deparser
control Bcast_deparser(
    packet_out packet,
    in headers hdr
){
    apply {
        packet.emit(hdr.ethernet);
        packet.emit(hdr.ipv4);
    }
}

V1Switch(
    Bcast_parser(),
    Bcast_verifyChecksum(),
    Bcast_ingress(),
    Bcast_egress(),
    Bcast_computeChecksum(),
    Bcast_deparser()
) main;

