control IngressI(inout H hdr, inout M meta, inout standard_metadata_t smeta) {
    Header h1;
    Header h2;
    H s1;
    H s2;

    action invalid_H(inout H s) {
        s.h1.setInvalid();
        s.h2.setInvalid();
    }

    apply {
        h1 = { 1 };
        if (hdr.h1.data == 0) {
            h2 = h1;
        } else {
            h2.setValid();
            h2.data = 0;
        }

        hdr.h1.data = h1.data;

// h1 valid at this point
        hdr.h2.data = h2.data;

// h2 valid at this point

        if (h2.data == 1) {
            h1.setInvalid();
        }

        hdr.h1.data = h1.data;

// h1 potentially invalid at this point
        h1 = h2;

// h1 valid again

        if (h1.data == 1) {
            s1 = { h1, h2 };
            s2 = s1;
            if (s2.h1.data == 0 && s2.h2.data == 0) {
                if (s1.h1.data > 0)
                    s1.h1.setInvalid();
                else
                    s1.h1.setInvalid();
                hdr.h1.data = s1.h1.data;

            } else {
                s1.h1.setValid();
            }
            hdr.h2.data = s1.h1.data;

        }

        invalid_H(hdr);

        hdr.h1.data = 1;

        hdr.h2.data = 1;

    }
}

