        hdr.h1[0].data = 1;
        hdr.h1[1].data = 1;
        transition next;
    }

    state next {
        hdr.h1[0].setInvalid();
        pkt.extract(hdr.h1.next);
        hdr.h1[0].data = 1;
        hdr.h1[1].data = 1;
        hdr.h1[0].setInvalid();
        transition select (hdr.h1[1].data) {
            0: init;
            default: accept;
        }
    }
}

control IngressI(inout H hdr, inout M meta, inout standard_metadata_t smeta) {
    H h;
    H h_copy;
    H h_copy2;

    action validateHeader(inout Header hd) {
        hd.setValid();
    }

    action invalidateHeader(inout Header hd) {
        hd.setInvalid();
    }

    action invalidateStack(inout Header[2] stack) {
        invalidateHeader(stack[0]);
        invalidateHeader(stack[1]);
    } 

    apply {
        validateHeader(h.h1[0]);
        h.h1[0].data = 1;
        h.h1[1] = h.h1[0];
        h.h1[1].data = 1;

        h.h2 = h.h1;
        h.h2[0].data = 1;
        h.h2[1].data = 1;

        h_copy = h;
        h_copy.h1[0].data = 1;
        h_copy.h1[1].data = 1;
        h_copy.h2[0].data = 1;
        h_copy.h2[1].data = 1;

        invalidateHeader(h.h2[0]);
        h_copy2 = { h.h1, h.h2 };
        h_copy2.h1[0].data = 1;
        h_copy2.h1[1].data = 1;
        h_copy2.h2[0].data = 1;
        h_copy2.h2[1].data = 1;

        bit i = 1;
        h_copy2.h2[i] = h.h2[0];


        h_copy2.h1[0].data = 1;
        h_copy2.h1[1].data = 1;
        h_copy2.h2[0].data = 1;
        h_copy2.h2[1].data = 1;

        validateHeader(h.h2[i]);

        h_copy2.h2[i] = h.h2[0];

        h_copy2.h1[0].data = 1;
        h_copy2.h1[1].data = 1;
        h_copy2.h2[0].data = 1;
        h_copy2.h2[1].data = 1;

        invalidateStack(h.h1);
        invalidateStack(h_copy.h1);
        h_copy.h1[0] = h.h1[i];

        h_copy.h1[0].data = 1;
        h_copy.h1[1].data = 1;

        h.h1[1].setValid();
        h_copy.h1[0] = h.h1[i];

        h_copy.h1[0].data = 1;
    }
}

