parser ParserI(packet_in pkt, out H hdr, inout M meta, inout standard_metadata_t smeta) {
    state start {
        hdr.u[0].h1.setValid();
        pkt.extract(hdr.u[0].h3);
        hdr.u[0].h1.data = 1;
        hdr.u[0].h3.data = 1;

        hdr.u[0].h1 = hdr.u[0].h3;
        hdr.u[0].h1.data = 1;
        hdr.u[0].h3.data = 1;

        transition select (hdr.u[0].h1.data) {
            0: next;
            default: last;
        }
    }

    state next {
        pkt.extract(hdr.u[0].h2);
        transition last;
    }

    state last {
        hdr.u[0].h1.data = 1;
        hdr.u[0].h2.data = 1;
        hdr.u[0].h3.data = 1;
        transition accept;
    }
}

control IngressI(inout H hdr, inout M meta, inout standard_metadata_t smeta) {
    Union[2] u;

    apply {
        u[0].h1 = { 1 };
        u[1].h1 = u[0].h1;
        u[1].h1.data = 1;

        bit i = 0;
        u[0].h2.setValid();

        u[1] = u[i];
        u[1].h1.data = 1;
        u[1].h2.data = 1;

        if (u[1].h2.data == 0) {
            u[i].h2.setValid();
        }

        u[0].h1.data = 1;


        if (u[1].h2.data == 0) {
            u[i].h1.setValid();
        } else {
            u[i].h2.setValid();
        }

        u[0].h1.data = 1;
        u[1].h1.setInvalid();

        u[i].h1.setInvalid();

// no effect
        u[0].h1.data = 1;
        u[1].h1.data = 1;

        u[i].h1.setValid();
        u[0].h1.data = 1;
        u[1].h1.data = 1;
    }
}

