parser MyParser(packet_in b, out h hdrs, inout m meta, inout standard_metadata_t std) {
    state start {
        h l;
        l = b.lookahead<h>();
        transition select(l.h[0].f1, l.h[1].f1, l.h[2].f1) {
            (1, _, _) : one;
            (0, 1, _) : two;
            (0, 0, 1) : three;
            default: many;
        }
    }

    state one {
        b.extract(hdrs.h.next);
        meta.h_count = 1;
        transition accept;
    }

    state two {
        b.extract(hdrs.h.next);
        b.extract(hdrs.h.next);
        meta.h_count = 2;
        transition accept;
    }

    state three {
        b.extract(hdrs.h.next);
        b.extract(hdrs.h.next);
        b.extract(hdrs.h.next);
        meta.h_count = 2;
        transition accept;
    }

    state many {
        meta.h_count = 255;
        transition accept;
    }
}

