        meta.counter = meta.counter + 1;
        hdr.vector[0].e = hdr.pool[1].val + 1;

// end legacy test.
        Index_t i = (Index_t) hdr.ml.idx;


// Test runtime index as l-value.
        hdr.pool[i].val = hdr.vector[0].e;
        hdr.pool[i].base2 = hdr.vector[0].e;

