        hdr.vector[1].e = hdr.pool[i].base0;

// Test runtime index as l- and r-values.
        hdr.pool[i].base0 = hdr.pool[i].base1 + 1;
        standard_metadata.egress_spec = standard_metadata.ingress_port;
    }
